insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "7170b64e-3d7b-4fe7-849b-a13c8b0873c3", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 2, "content": "Shandi Kano (00:04:10): Well, no, I, well, I started working at ESPN in 2008. I worked in digital media. That was kind of when digital media was becoming a thing. So highlights were having a second screen platform on your laptop or your phone. So I was cutting those in the digital newsroom and then transitioned into X Games work and then eventually full-time production for X games.com and broadcast. And then I left ESPN early 2014. And then in 2016, I had started an event with a couple of friends called essa, and it was a weekend long retreat for women in the mountains to learn new skills and find themselves to be more equipped to be out there on their own. And then we brought Sean in for some storytelling and that's how we met. And then he called me, I don't know, a few months later for some work.\n\nCole Heilborn (00:04:59): Cool. And now you guys are the tag team duo. Yeah.\n\nSean Slobodan (00:05:03): Yeah. So it's It's been nice. Yeah, work has just continuously kind of, I mean, it's a process of building a clientele and relationships and networking and things, and it takes a long time to find the right people to work with and to build trust. And I think Chandy and I have been working at it now for\n\nShandi Kano (00:05:30): Four years\n\nSean Slobodan (00:05:31): And it's worked out really well. So it's been a good tag team.\n\nCole Heilborn (00:05:39): So you guys just finished up, well, I guess it's been a little bit of time now, but you recently finished up a pretty amazing film called Forever. Is now the highlight or give us the story behind the film excited to dive into this.", "token_estimate": 401, "speakers": ["Shandi Kano", "Cole Heilborn", "Sean Slobodan"], "start_timestamp": "00:04:10", "end_timestamp": "00:05:39", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "fcbaff19-81d1-4cd7-92c1-149f93b29a4a", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 3, "content": "Shandi Kano (00:05:59): Okay, well, so in the fall of 2018, Sean called me one day and said, Hey, I'm going to send you this email. When you get a chance to read it, call me back. And I was like, okay, this is very interesting. But I did, and it was this call from Zion National Park Forever Project, which is the official nonprofit of Zion National Park, and they were requesting a new film for the visitor center. And so when you go to a national park, you go to the museum or the visitor center and there's a film you can watch that kind of orients you and generally pretty dated. And they were looking for something that they would say is not your grandfather's film. And so it was kind of this very exciting moment of, well, this is kind of the dream. It connects everything you love to do personally and professionally in places that have you've loved for a long time. (00:06:52): So it was super exciting. We got on the phone with them and started to hear their ideas, which was because Zion is kind of that poster child of overpopulation and over visitation, they wanted something that would inspire those visitors to become stewards or contributors to a park as opposed to just consumers going in for your photo and leaving. They wanted people to connect on a deeper level. And so for us it was just like, this is so exciting and awesome. And the idea morphed quickly, I think for us in our minds is this is so much more than just living in the visitor center. This message is relevant right now in this moment in time, especially what's been going on with public lands and their popularity. And so to make the long story short, we ended up pitching them on a much longer version as well as a short version of the film for the intention of releasing it into the wider world, which has been happening now.", "token_estimate": 454, "speakers": ["Shandi Kano"], "start_timestamp": "00:05:59", "end_timestamp": "00:05:59", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "776f78e7-1028-4879-bc8a-d79236b1443e", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 4, "content": "Sean Slobodan (00:07:53): And a couple of things I would add too is that when they reached out, they had, first of all just very flattered that they reached out. They had received local's name just from some other people in the industry that they had asked and inquired. And so to get that call from them just really flattering, super stoked, and it just turned out to be an amazing relationship that's continued to evolve and turn into a longer term relationship with these guys. We still are in very frequent contact with them. I mean, the film obviously is continuing to evolve and get out to new places, and so we're working together with that. But they were very open in to ideas. I mean, it was a very kind of different situation. A lot of times you have a client that reaches out and they kind of already have the idea of what they want very kind of strict as to the box that needs to fit in. And these guys were the opposite of that. (00:09:06): They wanted it to be a collaborative process. Were very open to new ideas, approaches, and it created a space that was just really great to work in with them because we were given a lot of freedom as to how to attack this project. And the main goal being like Shandy said, wanting to inspire people to stewardship, a different kind of visitation and impact in our national parks specifically, and trying to see it from a bigger picture and make it inspirational. So that was kind of the terms, and it was kind of a dream come true.\n\nCole Heilborn (00:09:50): That's like a filmmaker's dream when a national park calls you and they say, Hey, we need your help. We need to inspire a bunch of people. And they're like, oh, and you can film in our park. That's pretty cool. It's\n\nShandi Kano (00:10:01): Not every day that happens. Yeah, we were stoked\n\nCole Heilborn (00:10:07): And you ventured it into a bunch of film festivals, Vancouver International Mountain Film Festival being one of them. And you guys just won People's Choice Award, which is pretty cool. Congratulations. Thank you.\n\nSean Slobodan (00:10:19): Thank\n\nCole Heilborn (00:10:19): You.", "token_estimate": 527, "speakers": ["Sean Slobodan", "Cole Heilborn", "Shandi Kano"], "start_timestamp": "00:07:53", "end_timestamp": "00:10:19", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "59150d65-7675-4059-8db1-a1fb91b15aff", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 5, "content": "Sean Slobodan (00:10:21): I don't know if it was hometown treatment there, but I mean obviously it was pretty great to be able to have it premier at a festival so close to my home. And Shandy obviously from Alberta as well. So a lot of Canadian influence on this one, and it was cool to have it play there for sure.\n\nCole Heilborn (00:10:41): So a lot of things we talk about on this podcast are in the client side of things. We interview a lot of folks who are on the brand side, who are the people that are coming up with the goals of, oh, we need to be able to inspire people to appreciate our national parks and respect them. We haven't had a lot of voices on the other side of that, the people who then those people go to and figure out actually, how do we do that? And obviously film is such an amazing tool to be able to communicate a message like that or many others. That's why we love it, that's why we do it. But I'm really curious to dive into how you guys went through taking this goal and actually turning it into something that is effective and communicates that story and that emotion and inspires your audience. I guess from a big picture level, how did you initially approach this idea and what ideas did you try? What things did you avoid?", "token_estimate": 315, "speakers": ["Sean Slobodan", "Cole Heilborn"], "start_timestamp": "00:10:21", "end_timestamp": "00:10:41", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "39bcc32c-4024-4ad9-bbde-1983853f178b", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 6, "content": "Sean Slobodan (00:11:41): Yeah, I mean it was interesting because they actually had a couple of ideas, even a script for the project. So the amazing part about it's, they'd always kind of put out an idea and go like, but hey, this is just us and we're just paying for everything, but I take it or leave it. This is just an idea. If you think it'd work, if you don't think it would work, let us know. And it was just they were always so like, Hey, this is something, here's something we could do, or here's an idea, but let us know what you think. And I think throughout my career as a filmmaker, every project you work on, you learn more about your own voice and your own style and your own approach. I think we all packed probably 10 years of experience into this one year because of this project, but you just have your past experiences to pull on and go, okay, well here's something that, an approach that I know works for me that I feels true to me. (00:12:55): And so we just use that as a bit of a blueprint to say, Hey, we've told a lot of short docus style stories in the past and that's where a lot of my experience comes from web content or commercials or things that you're dealing with real people and you're trying to tell an authentic story often in a five to eight minute window. And we felt like, okay, well they have all this information. They talk about wanting to educate on the geological aspect and the flora and the fauna and the water in the park and the colors of the rocks and the Colorado plateau and all of these things that are often a part of films like this where it's just very educationally focused. And so that was where a lot of the ideas were coming from and they felt like it's still important to have this in there. (00:13:53): And so we kind of took that and went, in our experience, what audiences have most connected with. If you're wanting to have somebody walk away from a film or a piece of content changed or with a different idea or with a different perspective, you have to obviously connect with them on a personal level. And I don't know of a better way of doing that than telling authentic stories of us of other people. And I think that's why we get inspired to do the things that we set goals to do or want to do or be like is we see other people doing it and we go, I want to be like that, or I want to try to do something like that. And so I think we took that and just try to apply it into, well, how do we take some real stories and work in some of these aspects that they're interested in still kind of being a part of this project that are important? And we found that you can do that through people that are personally connected through the park and just, we basically just said, okay, well how many people stories can we fit into a 25 minute piece or a 45 minute piece? And that's where we started. We went, okay, we can probably fit, I don't know, somewhere between two and 10. So then we just kind of started whittling down from there and trying to identify characters to fit in,", "token_estimate": 760, "speakers": ["Sean Slobodan"], "start_timestamp": "00:11:41", "end_timestamp": "00:11:41", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "0b49fc3c-3fe8-4f70-b635-68863af4322a", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 7, "content": "Cole Heilborn (00:15:27): But at the same time, you got to find those individual stories, but then those stories all have to converge and connect in some way, otherwise they just feel very scattered and they're not working towards something bigger than each of their individual stories. So yeah, this kind of gets into the grittiness of the characters and how you choose characters. How many did you end up with and what were, for folks that haven't seen the film, one, you should watch it when you can, but who were those characters for you guys? Who did you discover and why?\n\nShandi Kano (00:16:04): Well, so we had a little bit of a blueprint when we talked about they wanted to talk about the elements of water and sandstone and wildlife and safety, plants, safety, all these sorts of things. So since we are outdoorsy people and we had interests in these things via activities, we kind of linked certain characters or hopeful characters to different elements they wanted to talk about. So with geology, we thought, well, what is cooler than canyoneering and what is cooler than understanding the land and its use? Then hearing it from a native Paiute person, we had to link the characters to these elements of nature. I think that helped tie it together because all those elements were essentially what we're working to preserve. (00:17:04): We whiteboarded a lot and we set ourselves a blueprint of here's all the different elements and here's all the different things you can do, and here's all the different kinds of people. Because one of the goals too is this isn't supposed to speak to one kind of person or one kind of activity or one group. This is for everybody, people who come to the park twice a month, people who come to the park once in their lives, people who've never been. And so we had to make sure that we would cover bases with characters that would speak to all sorts of people. So between that, between the elements, between the activities, I think we started to line up on characters. And so the characters ended up being a couple of park rangers, a guy who's lived there for a very long time, a farmer, a local rancher", "token_estimate": 537, "speakers": ["Cole Heilborn", "Shandi Kano"], "start_timestamp": "00:15:27", "end_timestamp": "00:16:04", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "57d6b80a-3d88-4c28-841d-54b14898ce87", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 8, "content": "Cole Heilborn (00:17:57): Who's a fabulous musician and singer.\n\nShandi Kano (00:18:01): Yes, so Leon, a Paiute family, a foreign tourist who came to from Japan to Zion for the first time, a couple of rock climbers, a couple of canyon years school kids. Water was a character that we made intentional, like water was a character. It's not a person, but it was a character. That's only seven. Who are you missing? James. James\n\nSean Slobodan (00:18:26): And a planar artist,\n\nShandi Kano (00:18:28): A plain air artist.\n\nSean Slobodan (00:18:30): Yeah, I think we just kind started with what we had. The park had identified certain things they wanted to include history of the park, kind of how the park was formed. They wanted to talk about the geology and just the uniqueness of the rock formations there in the park, just the craziness of those cliffs and those walls and the beauty of that, the role of water in the park. They wanted to talk about safety, they wanted to address wildlife, wildlife, flora, fauna. So we had all of those things and it's just kind of going, okay, well here's a subject or an item. What kind of person would be able to connect in a personal way with this thing? And the focus? I think a big part of the discussion at first was moving away from just over flooding with information rather than and more focused on telling this person's story and it being connected to that aspect of the park. (00:19:52): So we often talked about less is more. I think oftentimes there's just so much information and so many things you want a viewer to understand, but when you give too much, you actually get less out of that. Whereas if you can inspire and introduce them to a certain thing, we can leave a space or leave a film and then on our own go and search and learn more about it. And I think that was the goal with a lot of this was to inspire people to learn more on their own, to start connecting their own dots, but to give them a starting place to do that.", "token_estimate": 496, "speakers": ["Cole Heilborn", "Shandi Kano", "Sean Slobodan"], "start_timestamp": "00:17:57", "end_timestamp": "00:18:30", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "0ea998c3-a3c4-4c23-8fb8-b240b5248b79", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 9, "content": "Cole Heilborn (00:20:27): Yeah. So it sounds like you had your objectives from the client and from your just personal goals for the project, and then you started to map out who you ideal character would be to reflect those objectives. Is that what you're saying?\n\nSean Slobodan (00:20:40): Absolutely.\n\nCole Heilborn (00:20:41): Gotcha.\n\nSean Slobodan (00:20:43): If you talk about geology, first thing that came to mind for us, Zion is an iconic place for climbers, and climbers have played an important role in our national parks in the United States and really all over the world. And so we felt like that would be a great fit. We could find somebody with a personal story, a personal connection to Zion. It would also obviously visually give us an opportunity to really show off the beauty of that red rock in the park, but show a person who respects the place. And still climbing is an interesting part of the story because climbers have, and maybe we don't need to get into this, but climbers have a tremendous impact in national parks, some for good and some for not so good. And so it was definitely, yeah, I mean it was tough. I mean, just climbing in general, such a polarizing can we found out, I mean, firsthand experience can create such a polarizing effect on people. (00:22:05): If climbers are so passionate about these places, often climbing and activism kind of go hand in hand and they're viewed as going hand in hand. And yet you find out that there's the opposite side of that. People are very against those types of activities in the park, and do they create more harm than good? And so there was a whole kind of different discussion that came from that aspect, but you just kind of go, okay, well, who would be a good character to talk about history? Well, who's been around the park for 350 years, probably a local farmer. And so these are just ideas we're throwing up on the board, and a lot of 'em ended up turning into real people that we were able to connect with.", "token_estimate": 498, "speakers": ["Cole Heilborn", "Sean Slobodan"], "start_timestamp": "00:20:27", "end_timestamp": "00:20:43", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "47614152-bf7f-423d-9caf-c762c64beb59", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 10, "content": "Cole Heilborn (00:22:56): So you come up with this dream character, a farmer or a native individual, and then you have to go find them and make sure that they're actually willing to be on camera and can speak to what you want and can actually articulate thoughts on camera. How do you do that from a logistical and from a creative perspectives?\n\nSean Slobodan (00:23:17): Well, it's funny because we hadn't actually won the project yet, but we were, as often happens, you put together ideas, a big pitch deck, and you go in and you try to go, Hey, here's our vision. Here's what we think would work, and here's why. So we had at that point, this is end of 2018, we said, okay, here's all of the kind of areas that we want to touch on in the film that we've discussed together. Here are the characters that we think would work best to get into those topics or get into those areas of discussion. And so we had these kind of make-believe characters climber that has a goal to climber here, old timer here, ranger in the park. And so we had all these kind of theoretical people, and then they go, this sounds amazing, let's do it. And then our team afterwards, we kind of look at each other and we're like, well,\n\nShandi Kano (00:24:21): It's go time\n\nSean Slobodan (00:24:21): Crap. Now we actually have to find people that fit into these. They've approved it, signed on the dotted line, and now we actually have to deliver these people that we don't even know if they exist. So luckily it worked out, but it was an interesting moment for sure. We were super pumped to be able to move forward, but it was definitely learning as we went. We'd made people up, and now we had to actually find the real versions.\n\nShandi Kano (00:24:51): But I think it wasn't like they were made up in a way where it was farfetched. They'd exist.\n\nSean Slobodan (00:24:54): I mean, I've been around humans before, so I knew people like that existed somewhere. I just didn't know them specifically.\n\nShandi Kano (00:25:01): I didn't know that was a moment where you went, oh crap.\n\nSean Slobodan (00:25:03): Oh yeah.\n\nShandi Kano (00:25:04): I went, oh yeah, I'm so excited.", "token_estimate": 538, "speakers": ["Cole Heilborn", "Sean Slobodan", "Shandi Kano"], "start_timestamp": "00:22:56", "end_timestamp": "00:25:04", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "ff5ebcd4-0071-4169-a37d-57762ef72779", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 11, "content": "Sean Slobodan (00:25:07): Well, we're walking out of the meeting and we're like, oh, this is stoked. We got the project. And then it's like, I don't know any of these people. The work was cut out.\n\nCole Heilborn (00:25:18): Well, that's where the producer really kicks in and starts to make things happen.\n\nShandi Kano (00:25:23): So okay, I think as you're speaking about this and the question comes up, I start to go, oh yeah, here's my answer. And then I'm like, oh, yeah, oh yeah. And I remember what a mountain this was to climb, and it was very exciting for me. I was very excited to, I'm not saying I was bummed out. I know you're not, but I was like, yes, uncharted territory. Here we go. I'm going to go find all these people. We had roles to fill, we had a brief to fulfill. We had a film to make with goals and sight. And so really it just comes down to hardcore networking and staying at it and really getting your elevator pitch down, understanding exactly what you're looking for and understanding how to use your network and how to connect with people to find and start to begin exploratory interviews with all of them, which is always a little bit of, well, what are you doing and why? And here's kind of what we're looking for, but it can't be so much like, are you this person that X, Y, Z? You really have to connect with them, understand what they're about, because those human elements start to come out and you start to see, well, this is how it fits in. And so I mean, at one point we said, are you just everything against the wall and seeing what sticks? And it's like, well, but it's not without direction. You know what I mean?", "token_estimate": 414, "speakers": ["Sean Slobodan", "Cole Heilborn", "Shandi Kano"], "start_timestamp": "00:25:07", "end_timestamp": "00:25:23", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "e381feab-8fd5-4bfd-8fb7-618a8464556b", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 12, "content": "Sean Slobodan (00:26:52): Yeah. I mean the main goal for the whole thing was the approach was, and it always I think will be for us, this is just how we have gone about our filmmaking, is telling real human being stories. And I think that's always going to be the most effective way to connect with audiences is if they sense they're experiencing something that's real and not fabricated. I mean, you're always going to have an agenda. I think even the most objective oriented person is still going to end up with an agenda. We definitely had an agenda with this. We want people to be better stewards in our national parks and to treat these places with way more respect than we currently do. And to understand our impact in those places, that's our objective. But I think telling real human stories is always going to be the best way to go about it. And whether you're selling a product or whether you are just sharing your life, I don't think it matters. I think the whole goal with content is to connect with people and telling each other's stories in an inspiring way is going to be the best way to do it.\n\nCole Heilborn (00:28:24): So you're sitting there listening to a hundred people tell their story. What are you looking for? What makes a good story from an individual? What stands out to you guys as you're listening to these people talk?\n\nSean Slobodan (00:28:39): Do you want to tell him about Hitomi?", "token_estimate": 354, "speakers": ["Sean Slobodan", "Cole Heilborn"], "start_timestamp": "00:26:52", "end_timestamp": "00:28:39", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "eb4d9b86-9ee5-480d-979a-aa243a78829d", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 13, "content": "Shandi Kano (00:28:40): I will, but I will say this too. That process is like I'm taking direction from Sean and Travis who's the co-director on the film. They're the ultimate, the last say in the creative decision. And they've got these ideas and we've all kind of mapped out the kind of people we want. And so as I'm going through doing exploratory calls and trying to decide ultimately who I can bring back to Sean and Travis for them to say, yes, we're headed in the right direction. So it's very much synergistic and how we're working together. And I'm constantly, okay, interviewed this person today. I don't think they're the right fit, but I would generally gather a few options per character, bring them back to Sean and Travis and kind of say, here's why I think these people can work. And I'd kind of go through things and it ultimately comes down to them being like, okay, let's talk more to this person, or I want to talk to this person. Initially, it's just me kind of sourcing and feeling things out. And if I feel like it's a good fit, bring it back to them, then we'll get on a larger group call. They'll do a deep dive with this person, but ultimately they have the last say in that call, it's a creative decision and I'm working to fulfill that order or that vision. (00:29:55): So that's the process, and it just kind of keeps whittling itself down until we get to a point where we are kind of dialing in their story that's going to be portrayed in the film, and we're going through that with them and pulling out the pieces we want to focus on. And anyway, that takes us in a different direction. But the question was how, and for me, the answer really comes down to it's made easy when you have talented directors who know what they're looking for and understand how to understand people, how to connect with people, how this person's story is going to play out on camera, and ultimately how the world is going to be able to see them. (00:30:38): And so I think this example that I was sharing with Sean earlier, I spent from, gosh, January until July trying to find a person overseas to come. And honestly, probably before January too, the park had ideas on people who were overseas who could be visitors in this role. And we spoke to people in China and India and Japan, and it was like June, I think it was after or when we got linked up with one of our partners, they had a distributor in Japan who ran a women's outdoor company for retreats and things. And they said, why don't we link you with her? And this is after months. And we had a couple people and it just didn't feel right. And so I interviewed five or six other women from this group in Japan, and I felt like there were three good candidates and nothing was really sparking that was like, this is a home run. But I brought these three to Sean and Travis, we all interviewed them, and there was kind of this thing where it was like, well, who do you really want? Who do you really want? I was just like, I think they'll all be fine. But ultimately it came down to Sean and Travis feeling like this one person would be more able and more willing to be emotionally open and vulnerable, which was something we had to pay attention to. Because Japanese culture is so different from ours,", "token_estimate": 818, "speakers": ["Shandi Kano"], "start_timestamp": "00:28:40", "end_timestamp": "00:28:40", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "4e4ea043-bf7b-4098-9e1b-5c4f36e1ab0a", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 14, "content": "Sean Slobodan (00:32:20): My sarcasm does not transfer over very well, and pretty much I rely a lot on that aspect of my personality. So I needed somebody who was going to at least get that, you know what I mean? Or appreciate it.\n\nShandi Kano (00:32:36): But I think that decision was made because they could see something that I couldn't, quite frankly, which was that this person who we ended up choosing Hitomi, would be more willing, capable to open herself up and to share her feelings and emotions with us. And I cannot tell you how amazing it was to watch that idea that they had come true. She was incredible. And one of my favorite characters of the film, it's very hard to pick favorite, but I don't know what you want to call that was spot on. And her story just became such a beautiful moment for all of us. And I dunno that it would've happened. I mean,\n\nSean Slobodan (00:33:29): I remember when we were speaking with Hitomi and we were also speaking with a couple of the other women that we were interviewing over in Japan. I was on the road with my family, we were driving to, I think we were driving to Canada and we stopped at a hotel and I was trying to get all the kids, my wife and I have three kids, we're trying to get everyone in the hotel. I'm on my headphones, I'm trying to hold my phone like this. And I remember I just had to get kids in the hotel room. I gave my wife the sign off and the good luck. And then I closed the door and had to go out in the hall and then try to focus on me, okay, are you going to be emotionally available to me? And it was an interesting time, but that was just kind of how it worked through that process was it was all the time, and that's a whole different aspect of it, but it was all day every day for a good year. We were finding characters filming in the park already working on the edit. It was all aspects of the production were happening at the same time and at all times of the day.", "token_estimate": 488, "speakers": ["Sean Slobodan", "Shandi Kano"], "start_timestamp": "00:32:20", "end_timestamp": "00:33:29", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "44f4ea08-62ef-4257-8945-3f0b5a6b4a19", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 15, "content": "Cole Heilborn (00:34:56): So yeah, that's a really good example. You're chatting with a few different folks, three of them stand out, but one of those three, you just kind of have a hunch about what is it about that person that makes you think they're going to open up and fill that role and surprise you with more than you could want when they're on camera, essentially you're taking a big risk, inviting someone into a film, inviting them not only from the financial aspect, but also from the story because you're inviting them into this story and they have to fit and they have to kind of meet this expectation, but you don't really know if they will prior because people change when they're on set and they're in front of the camera and they can clam up or they can open up. But what is it about those initial conversations? What are you noticing? What are those nonverbal things that you're picking up on that help you trust that hunch?", "token_estimate": 236, "speakers": ["Cole Heilborn"], "start_timestamp": "00:34:56", "end_timestamp": "00:34:56", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "c6115e52-6aaf-40f0-b715-835073a8c20a", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 16, "content": "Sean Slobodan (00:35:58): I don't know. I mean, I think that's a good question, but I don't know that I really know the answer to that. It is just time and experience. I think just sharing time with lots of different people. I think for the most part it's just learning how to trust yourself. And I've made plenty of wrong calls with people and had plenty of horrible interviews and just trying to pull from that in moments like this, just to try to do the best you can and you just kind of have to live with the outcome. And sometimes it works and sometimes it doesn't. But I think luckily over time you just get better at it. I mean, I love talking with people and getting to know them. And so I think an important aspect in thinking about it now is if you are real and open and emotionally available to someone that you're getting to know, they're more likely to reciprocate that and be open and available to you. And that's not going to happen with everyone. But I think everyone that ended up in the film, it happened with to a certain degree, and I think we were able to kind of trust that with the Tommy. I mean, we flew out to Japan before we'd ever met her. We didn't know what her apartment looked like. I had ideas of shots that I wanted to get, but I had no idea how we were going to get them. (00:37:41): Yeah, I mean it was an incredible leap of faith on both parts. She didn't know us, she didn't know what our process looked like. She didn't know what she was inviting into her apartment and her work and her kind of just circles of family and friends, her\n\nSpeaker 4 (00:37:59): Family.", "token_estimate": 401, "speakers": ["Sean Slobodan", "Speaker 4"], "start_timestamp": "00:35:58", "end_timestamp": "00:37:59", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "4470b8f8-ed77-4c9b-bda7-f2cd2974c3dc", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 17, "content": "Sean Slobodan (00:37:59): Yeah, I mean it was a lot of trust on both parts. And I think to be honest, I think when both parties are going out on a limb for each other, I think good things are going to happen. (00:38:12): And so there was a connection when we were talking with the Tomi. There's a connection when we were talking with other characters as well, and we just kind of trusted that there were definitely people that we talked to. It was like, Nope, that's not going to work. She didn't laugh at my joke. So yeah, I mean your personality comes into it as well. I mean, you have to be able to work with people that you can get along with and that you can share a good time with. And yeah, I mean there's a lot of aspects to it, but essentially it just came down to trying to trust how we were feeling and if we felt like we could get close to this person, we had to trust that feeling.\n\nShandi Kano (00:39:06): I would add, I think, and this is just because on a production side of it, I am half creative and half not creative, but like I was saying earlier, if I felt something was good, it was really, I had to trust these guys to make that final decision. And I think that's kind of this invisible gift, invisible creativity that\n\nSean Slobodan (00:39:28): I don't think you give enough credit to your creative side, by the way. Just draw it out there. Continue.\n\nShandi Kano (00:39:34): Thanks, John. But I think I forget what I was going to say. I'm just so flattered right now. Am I blushing? What was I saying?\n\nSean Slobodan (00:39:47): Trust?\n\nShandi Kano (00:39:48): Well, no, I think I just really felt it was such a joy for me to watch these guys have these ideas and just have them become real. And it was fulfilling for me to bring them things that could fulfill that. But ultimately there's an invisible creativity and this gift that these guys have to be able to connect with people that way to understand what they're looking for and know what it is when they find it. And so I just think so much credit to Sean and to Travis for that process.", "token_estimate": 518, "speakers": ["Sean Slobodan", "Shandi Kano"], "start_timestamp": "00:37:59", "end_timestamp": "00:39:48", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "738beb3d-c84c-4d0b-b8a0-935834c110c9", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 18, "content": "Cole Heilborn (00:40:23): One thing that's fun when you find characters is you kind of find a little bit of yourself in them or you learn something about yourself through them. For each of you individually, were there characters in your film that you really resonated with or just felt some connection to beyond the long hours that you spent with them\n\nShandi Kano (00:40:47): All? I will answer because it makes me a little emotional because Hitomi was just really incredible. I actually dunno how to answer this. You'll have to answer first, but I'll think about why I loved her so much.\n\nSean Slobodan (00:41:06): Yeah, I am trying to think how to answer that question. I mean, I don't know that I'd actually be able to pick any one specifically because we were able to connect on a very personal level with all of them. Leon, he's the old timer in the film, been living in Rockville just outside of Zion National Park for longer than I've been alive. And he just has such an amazing connection with that place. I mean, I've brought my kids back to his house and he's able to kind of take him around his little rickety farm with one of the most rundown milking cows that you will ever see in your life.\n\nShandi Kano (00:42:03): He also\n\nSean Slobodan (00:42:03): Has a cat guess he's seen better days.\n\nShandi Kano (00:42:05): He has a cat hotel.", "token_estimate": 338, "speakers": ["Cole Heilborn", "Shandi Kano", "Sean Slobodan"], "start_timestamp": "00:40:23", "end_timestamp": "00:42:05", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "e631a02e-0cdc-449f-913c-172c967e779e", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 19, "content": "Sean Slobodan (00:42:07): He's got a cat hotel. He pretends to blow up his bicep by blowing into his thumb. Kids just eat it up and he is just guy like that. I just grew to absolutely love him and adore him. And tell me, Phil, one of the park rangers, we were able to connect with him in so many, yeah, I don't know. That's a tough question. What is interesting is we were able to work with the Bullets family and they're the Paiute family in the film and stuff like that. I personally feel very unqualified to kind approach or talk about or make a film about because I have no experience there. And I am one of just like everyone else, I just come into Zion National Park and I walk around the trails and I take pictures of myself and my family and then I go home. And for the bullets family and their culture and their people and their history, it's so much more than that. (00:43:23): And there I am trying to make a film about this place that they have a much more deep and personal connection with and history with. And so being able to get to know them, for them to trust us they did, to be involved and be okay with being a part of this, for trusting us to tell some of their story and include it and intertwine it with all of the other stories in that piece was extremely special. And I felt I just really honored to have that because who am I to tell their story and just try to be willing to learn and not become an expert as soon as I learn one thing and act like I get it. But just really honored to be able to include that in there. I think all of the characters, I don't know. I think being able to connect with them in a personal way, all of them is the reason why they're in the film. And the reason why I think I feel that it works.\n\nShandi Kano (00:44:40): And your question was, did we connect with a character more the most, or what was your question?\n\nCole Heilborn (00:44:47): Yeah. Throughout the process, was there anyone that you guys really connected with and learned from or felt a part of yourself with them?", "token_estimate": 509, "speakers": ["Sean Slobodan", "Shandi Kano", "Cole Heilborn"], "start_timestamp": "00:42:07", "end_timestamp": "00:44:47", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "3685b90f-e4d3-4916-829c-50d7f00f2539", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 20, "content": "Shandi Kano (00:44:56): Yeah, I think all of them, to a certain degree you get connected with, especially as you're preparing to interview them and you're thinking about their story and you're thinking about your needs as a filmmaker. And so I think it happened with all of them on a certain level. And no doubt in honor every time someone can let you into their life that way. And I think when you're in that moment or in an interview like that and they're letting you in and you guys are both feeling things, I mean, that is just such a magical thing. You know what I mean? And that's an honor. So you connect with them all I think on that level. But for me personally, I learned so much from Hitomi. I think a little part of it is my family's Japanese, and so to see her cultural values play out resonated with me on a really personal level. (00:45:50): But also she had this joyful youth feeling about her and she's, I think she was 45 or 46, but she just felt like this very pure, happy, open, loving. She wanted to explore, she wanted to understand, but she noticed all the little small things about whether a plant or an animal, but she could connect that tiny little things she noticed to a larger scale of life for her and she could find a lesson anywhere. And I think that that resonated with me, I think because she was just so slow and intentional and she just found the joy everywhere in little things. And she just had mind blowing things to say. I mean, she's got really good English. And that was a big blessing I think because her friend Pauline was there to translate for us, but to hear Hadomi say certain things in her own, she struggled through English to communicate was just really, really powerful. I felt like she transcended that language barrier beyond I think what I would've ever expected.", "token_estimate": 455, "speakers": ["Shandi Kano"], "start_timestamp": "00:44:56", "end_timestamp": "00:44:56", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "8f9fc4e0-7c2b-4cd9-9c6e-765b6c8c6218", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 21, "content": "Sean Slobodan (00:47:06): Yeah. What was interesting too with the Tomi, when we started rolling out more kind of fine cuts of the film and sections of each character, Zion National Park, it's a government entity and we had to get everything approved by them. And so definitely some of our creative liberties were not as appreciated by some, which it's always an interesting process to work through. But I remember specifically her section kind of turned into, she just kind of speaks high level and you connect with her very emotionally. She talks about being water and the qualities of water, how it's soft and yet powerful. And for me, I listen to that and go like, damn, that speaks to me. And it means a lot of things that I can't quite put into words, but it means something. And we had some of the representatives at the park, their feedback was like, what is she talking about? Why is this in here? This doesn't make any sense. (00:48:22): Lots of different people, some people so literal, other people just we'd get comments from other people going so powerful. What she says, there's something about her personality. And I think if you look at Hit's story, if you're just strictly going literal, you're kind of like, well, what's the point? What is she actually saying? So it was definitely striking a balance throughout the whole piece of some of the decisions. Unfortunately, and maybe fortunately I'm probably way too out there with the way that I want things to be, but we had to come at things super literally, and other times we would really push to keep it a little more ethereal and high level where it can be interpreted a bunch of different ways. And Hemi's story is definitely that way where she says a lot of things that feel very authentic and you kind of have to interpret it your own way.", "token_estimate": 453, "speakers": ["Sean Slobodan"], "start_timestamp": "00:47:06", "end_timestamp": "00:47:06", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "c6c3a300-26ce-46d9-b4d9-6d295bd34989", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 22, "content": "Cole Heilborn (00:49:30): Yeah, I mean, I guess that makes sense when you're considering one of your goals is you need this to speak to a bunch of different people, and obviously someone can say words and we can all take those words and interpret them and associate different meanings with them, but when someone says something that's a little ambiguous, but it's more about how they're saying it, that's when I feel like everyone can connect to that in a different way and having a totally different interpretation and talk about finding a great character or characters, finding someone who can, I don't even know what that is, but they're just there helping connect dots, but not pushing the audience to do it. They're just providing a space for those dots to be connected. Does that even make sense?\n\nShandi Kano (00:50:17): Totally. Yeah. And that was kind of like Sean said this all year, we want to present this in a way where people have to go, okay, what do I feel about this? As opposed us going, here's how you should feel, and look at why we wanted it to be done in a way where someone could come away and go, huh, I never thought about that before. How do I feel about that? You know what I mean?\n\nCole Heilborn (00:50:40): Yeah, man, that's good. Transitioning gears a little bit, a lot of the folks, again that we chat with, other marketers are marketers. They're not the marketers. And storytelling obviously right now is popular. There's a lot of great films that have come out from some pretty awesome outdoor brands, but storytelling in itself kind of seems to be a bit of a buzz word when it comes to marketing practices or how to market as people who are deep in the art of telling stories. I guess, what would you say to brands out there that are wanting to tell real authentic stories besides hire you? What would you say in helping guide them as they're thinking about these concepts and maybe things they're trying to do and accomplish?\n\nShandi Kano (00:51:34): I think that the marketers really have, if they have to understand their end goal and if they want to tell a story, they need to understand why that story.", "token_estimate": 536, "speakers": ["Cole Heilborn", "Shandi Kano"], "start_timestamp": "00:49:30", "end_timestamp": "00:51:34", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "cc450090-1480-4b6c-bb70-06f4bd66648a", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 23, "content": "Cole Heilborn (00:51:47): Can you expand on that? What do you mean why that story?\n\nShandi Kano (00:51:52): I think if people are trying to be authentic, if you don't really believe or know why you're doing something, I think it's going to be hard for your audience to feel because there won't be anything for them to feel. I think passion is translated when it's put into a work like this, so if you don't know why you're telling a certain story, it's probably going to feel that way.\n\nSean Slobodan (00:52:20): I also think that it is going to come down to the team of people that you have.\n\nShandi Kano (00:52:28): Yeah,\n\nSean Slobodan (00:52:29): Absolutely.\n\nShandi Kano (00:52:29): I mean, yes, for sure.\n\nSean Slobodan (00:52:30): I mean, you have to have a good story. There's a lot of aspects. You have to have a quality story. You have to have a subject or a talent who's willing to be emotionally available. And then I think we just got really, I mean, I've never worked with another client like this Design Forever Project. It was such a collaborative experience, but they somehow just showed complete trust from the beginning. And I think our team really felt that, and it became a definite responsibility of not wanting to betray that trust. And I think that it happened to be two groups that just connected well, and that has not always happened. Most of the time it hasn't happened to that level, but I think you have to trust the people that you're working with. If you're going to hire somebody to tell a story for your brand, you have to have complete trust in that person because I mean, that's why you hire people to do certain things, right? (00:53:50): Because you hope that they're better at that thing than you are, or that they can see it in a way that's going to connect with people better than what you can envision. It doesn't mean that you do it poorly, it just means that you're trying to find the right people to do the right things, and there has to be trust across the board. So I think there's a lot of aspects to it. With us on this project, there was a lot of trust, and I think that that is what created a pathway for this thing to actually work.", "token_estimate": 546, "speakers": ["Cole Heilborn", "Shandi Kano", "Sean Slobodan"], "start_timestamp": "00:51:47", "end_timestamp": "00:52:30", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "1bc6727e-977f-4688-bfd7-6d74233d2804", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 24, "content": "Shandi Kano (00:54:25): I couldn't have imagined doing this, spending that much time with people that I didn't get along with, could argue well with, you know what I mean? If we didn't have that respect for each other. And again, I think that sort of symbiosis can come across in your work, but speaking to having a good team, I think when they called us, it's because they saw a piece of work we did a few years ago and right away they felt like this is the way we'd like to tell the story of place through people. And that's Sean's ability. And so it was probably easier for them to trust him and to trust his team when they were able to look and see this is what they've done before. So we trust you to do this for us. But again, because I'm better at bragging about Sean than he is, he has a gift. And so it makes it easy to trust someone like him. Are you okay? You're going to be alright.\n\nCole Heilborn (00:55:31): I'll\n\nSean Slobodan (00:55:31): Make it\n\nCole Heilborn (00:55:34): So we're kind of running out of time and I'm going to ask the question that probably could have an entire episode dedicated to it in itself, but what makes a story a good story?\n\nShandi Kano (00:55:46): It depends on what the brief is. A good story's going to be different for a different ask. Okay. But generally, what's\n\nSean Slobodan (00:55:55): Your budget, Cole,\n\nCole Heilborn (00:55:58): Sean? I've got a hundred dollars, but a lot more work in the future and I'm going to give you exposure bucks. Oh, and some\n\nSpeaker 4 (00:56:06): Portfolio\n\nSean Slobodan (00:56:07): Piece,\n\nCole Heilborn (00:56:07): Some gear? No, not gear, just yeah, exposure bucks. I'm going to tag you on Instagram. Okay.\n\nShandi Kano (00:56:17): Okay. You answered\n\nCole Heilborn (00:56:18): That question. Of course. I'm not that great at\n\nSean Slobodan (00:56:19): Instagram. So\n\nShandi Kano (00:56:21): Here,", "token_estimate": 471, "speakers": ["Shandi Kano", "Cole Heilborn", "Sean Slobodan", "Speaker 4"], "start_timestamp": "00:54:25", "end_timestamp": "00:56:21", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "7a56f4eb-799c-4dd2-be4c-3b594b419831", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 25, "content": "Sean Slobodan (00:56:24): I dunno. I think it's a lot of, I mean it definitely is a lot of the same aspects of what we've discussed. A great story. What makes a great story. I don't know. Still this is for me, I always work from image out and I'm definitely, I set out to kind of be a cinematographer always. That was my main goal was to be able to shoot my own stuff. I didn't want to have to rely on someone else to try to paint the picture that I was seeing in my brain. And so I still very much work that way, which is definitely not true because in a lot of aspects, some of the best stories that I've experienced and seen, there's been almost like no regard for what the image looks like. But for me, in my style, I often, if there's an idea in my head, I just start with some frames that I can see or some images that I see and build out from there and see if I can kind of put together a beginning, middle, and end. I don't know that it's actually a great way to answer that question.\n\nShandi Kano (00:57:45): Makes a good story story.\n\nSean Slobodan (00:57:46): Yeah, that's more of an observation.\n\nShandi Kano (00:57:49): It is interesting though, because when I started working with Sean years ago and I came in to look at an edit, like a first rough cut that we were working on, I was like, well, Sean, where's the words? I logged the interview and I highlighted stuff and we went through this, but it was all visual and it was really crazy to see that you had told the story straight up with visuals and no words. I was like, mind blown.\n\nSean Slobodan (00:58:15): Well, let me say this. Let me say this. I think I'm always about, again, trying to tell a story with the least amount of words as possible. I think obviously talking has its place in films and stuff that we create in content, and we've said a lot of words on your podcast today.\n\nCole Heilborn (00:58:38): We can make it entirely visual.", "token_estimate": 479, "speakers": ["Sean Slobodan", "Shandi Kano", "Cole Heilborn"], "start_timestamp": "00:56:24", "end_timestamp": "00:58:38", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "d7db2c09-1b08-4cea-bf0b-59a45afe7a7e", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 26, "content": "Sean Slobodan (00:58:41): I think that the more that you can say visually, I think that it has a certain power to it that, I mean, because if people are engaged, if it's engaging enough that people are paying attention, they're going to connect their own dots and they're going to create their own conclusions and come away with their own ideas that are much more powerful than me telling them what to think. And so I think for me, a good story is something that the visuals, yeah, I think the visuals can play an important part of, and that doesn't even need to mean that they're beautiful. I think that visuals can mean how you shoot something, how the camera is working to tell that story the way that it's shot and it moves and things. But I think visuals for me are really important in a way that a good story is told.\n\nShandi Kano (00:59:42): I have a logistical way to answer that question.\n\nSean Slobodan (00:59:44): Okay.\n\nShandi Kano (00:59:46): What makes a good story I feel like would be, it has to fulfill all the requirements you have for it, which could be high level emotional connection. It could just be visual, it could just be certain asks of a brief. But I think, and that's what my first thought was when he asked that question is like, well, it's going to be different every single time, but a good story is going to hit all of your marks, and those marks going to be different every time.\n\nSean Slobodan (01:00:15): Something that requires the viewer to engage and come away with an idea. I think that's what makes a good story. Something that requires something of the viewer for sure. That doesn't just lay it out for them.\n\nCole Heilborn (01:00:32): Yeah, man, I love that.\n\nSean Slobodan (01:00:35): You ever watched the film Baraka?\n\nCole Heilborn (01:00:37): No.\n\nSean Slobodan (01:00:39): Straight up. Just visuals, the whole thing really. There's not one word and it's one of the greatest films of all time.", "token_estimate": 485, "speakers": ["Sean Slobodan", "Shandi Kano", "Cole Heilborn"], "start_timestamp": "00:58:41", "end_timestamp": "01:00:39", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "bb02dcd7-b42e-43b4-afa3-68f76c5b63c5", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 27, "content": "Cole Heilborn (01:00:47): I'll have to look it up. Well guys, thank you. If folks want to follow along with the work that you're doing, if folks want to find the film, where can they find it? Keep in mind this episode is coming out next year in the spring sometime. So where can people find it?\n\nSean Slobodan (01:01:05): There's a feature length version, which is doing a festival tour right now, and we'll go on to do other things after that. And we, which is titled Forever is Now, and it's basically just a longer, slightly different, well different in a bunch of aspects, but it's a longer version. And then there was the version that we created for Zion National Park to play in the museum, theater in the park. Obviously this year has been super weird. So it had a grand four day run in the museum before things shut down. And we decided with the park to actually put the film online. So you can watch the 23 Minute Park version, which is entitled We The Keepers. You can see that on zion park.org. You can see it just on their YouTube channel, the Zion Forever Project, YouTube channel. And then we will have other places that you can watch the feature length version, whether it's in festivals, we'll be doing some screenings with film partners that we'll put out news about.\n\nShandi Kano (01:02:18): There's a couple festivals set up for the new year, like January, February. But after that we definitely want to have a long self-distribution run and that will start to take shape over the next few months.\n\nCole Heilborn (01:02:30): Okay. Well then people want, where can they go to learn will the film might be in the future? Is there a website, a social page?\n\nShandi Kano (01:02:37): Yeah, you could hit up local studio's Instagram page. It's lcl.studio.\n\nSean Slobodan (01:02:44): The website is forever film dot zion park.org, and it is up now. It doesn't have all the updated information, but by the time you're listening to this and hear it in your ears, it will be updated.", "token_estimate": 498, "speakers": ["Cole Heilborn", "Sean Slobodan", "Shandi Kano"], "start_timestamp": "01:00:47", "end_timestamp": "01:02:44", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "69047496-d858-4e08-8151-f979156cf9d3", "episode_id": "de533042-bfb1-460a-881f-10e1267ee3b2", "cms_item_id": "68225dfc7bb476527f8c4855", "chunk_index": 28, "content": "Cole Heilborn (01:02:59): Sounds good, guys. Well thank you. I appreciate you taking the last little bit of an hour to chat and I'm excited to rewatch the film and see you guys continue to do well in the festivals and hopefully you've got some more cool projects in the works that we can look forward to coming out in the next couple of years. Definitely. For sure. Alright, well have a good rest of your day and we will chat later. Thanks Cole. Thanks Cole. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 168, "speakers": ["Cole Heilborn"], "start_timestamp": "01:02:59", "end_timestamp": "01:02:59", "podcast_index": 49, "episode_name": "Ep 49: Sean and Shandi | An Award Winning Story | Forever is Now", "slug": "ep-49", "web_url": "https://www.portsidepro.com/podcast-feed/ep-49", "guest_name": "Sean Slobodan and Shandi Kano", "guest_title": "Filmakerrs", "categories": [], "short_description": "Filmmakers Sean Sloboda and Shandi Kano join me to discuss their latest, award-winning, documentary film", "podcast_length": "44:71"}, {"id": "934bc2bf-e533-40fb-bbe8-c93d4bd6552f", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 0, "content": "Cole Heilborn (00:03): Welcome to Brand Story, the podcast where we interview marketing professionals who are designing and creating the brands we interact with every day. My name is Cole Holborn. Today I'm here with Doug Thilan, the marketing director at Filson. Doug, how are you? Great. How are you doing? Fantastic. Thanks for being here.\n\nDoug Thielen (00:17): Yeah, thanks for having me decided\n\nCole Heilborn (00:18): To be a part of it. Before we jump in any further into your role and what you do, let's talk about Filson. Let's talk about the history. Where'd you guys come from and how does that shape who you are today?\n\nDoug Thielen (00:31): Yeah, Filson is a Seattle-based company. I've been around a few years since 1897. Started when the Gold Rush really was hitting its boom with CC Filson himself, seeing the opportunity to outfit prospectors and adventures heading up there. We've been in continuous operation as an outfitter and purveyor of outdoor goods since then. So we often refer to ourselves as 120 plus year old startup, which some people will say that's not a thing. How can you say that? But I think the business and the brand that we built here in the last five years has been something that is very much a startup mentality. But yeah, that's a quick one on the\n\nCole Heilborn (01:10): Industry. Yeah. So how does Seattle play a role in your brand? How does that fit?", "token_estimate": 350, "speakers": ["Cole Heilborn", "Doug Thielen"], "start_timestamp": "00:03", "end_timestamp": "01:10", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "ef3ddecf-efa3-43c8-9fe5-ed691380e230", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 1, "content": "Doug Thielen (01:16): Yeah, that's a good question. I mean, I think Seattle and where Seattle has been and the Northwest in general, and the type of people that came here back in 1897, and you could argue that probably even in today's world of tech and pioneers that's drawn, folks who've had this adventurous spirit, be it in literally getting outdoors and going to the Klondike or making their claim in the timber industry or in the mining industry or in the tech industry. I think Seattle and kind of the attitude of what it builds and the people who come here who live here is woven into the people who work at Filson, who worked at Filson, who started Filson and came all the way through. Even today, looking at the folks who are on my team and I get to work with, they're outdoor at the core. There are people, it's one of those where you sit around on a Monday and it's fun to hear about the diverse experiences from people who are duck hunting to our mountain biking to skiing. It's fun to have folks who really enjoy being out in the outdoors and the northwest and what it provides. And I think you see that in the brand and in the products that Fen puts out there.\n\nCole Heilborn (02:25): So you walk into a store where we're looking down on your guys' flagship store right now, and you walk in and you feel like you're kind of walking back in time in a way as the marketing guy or as part of the team of the marketing. Tell me a little bit about the Filson brand and what that feels like and what that is.", "token_estimate": 379, "speakers": ["Doug Thielen", "Cole Heilborn"], "start_timestamp": "01:16", "end_timestamp": "02:25", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "8cd73370-312c-47c4-9b63-60f3d8be15e1", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 2, "content": "Doug Thielen (02:45): Yeah, and it's one of those things where I think when I came on board, a lot of folks could see it and knew it, and they knew it was the brand, but they had a hard time talking about what it was. (02:55): A lot of you could see something and go, yeah, that's Filson, that feels right. But describing it was often difficult. We set out in that, in this growth size side of our business to build a brand guide. I think that's one of the things we were talking about earlier is we call it the Fills and Operation Manual, and unlike a lot of brand guides that would just talk straight about where you are today as a brand, your vision, your values, your purpose, your mission. We knew we had a big task where we're 120 year old company. We wanted to find a way to talk to people about the brand, but you couldn't do that without talking about the history. And I think that's something we talk and feel a lot where Filson has once foot in the past, but by no means do we feel that we are beholden to it, are tied to it.\n\nSpeaker 3 (03:36): We\n\nDoug Thielen (03:36): Can absolutely have your other foot and our head focused on the future. We are an outfitter and we think through that a lot. What would an outfitter do? What we provide, what can we bring to the table? I often talk a lot about having a connection to the wild and then the wild and the unknown, and I think the wild can be a lot of different things for a lot of different people. What's wild to you? And I maybe vastly different than what's wild to someone sitting somewhere else in a different office doing a different thing. I think that's what starts to set Filson a little bit apart, is showing real people doing real things through our marketing, through our advertising, through our events that people may look at and go, I didn't know that still existed. I didn't know people still did those things. That's crazy. And it's a little bit of that wild and unknown, and that's one thing that's kind of fun too for me is those folks we see in features in our social, in our campaigns, in our creative, they're not models.\n\nSpeaker 3 (04:32): I", "token_estimate": 532, "speakers": ["Doug Thielen", "Speaker 3"], "start_timestamp": "02:45", "end_timestamp": "04:32", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "d54b14c1-d605-4b95-bbe6-39b78ce6683f", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 3, "content": "Doug Thielen (04:32): Mean, I guess they're technically a model because wearing a product and they're an ad, but those are real humans doing real things that we've got to know through our producers, through our content contributors that we're featuring, that we're finding. And I love it more than anything when someone's like, oh, look at that guy. He's never clearly wheeled an ax before. And it's like, well, actually, he's been logging for 37 years, so here, talk to Nick.\n\nSpeaker 3 (04:53): Do\n\nDoug Thielen (04:53): You want to tell him why you hold the ax that way? So it is fun to find ways to feature people that may not be at the forefront of what people think about from a fishing industry or logging industry or any of those sort pieces.\n\nCole Heilborn (05:08): Yeah. What is the value of a brand? Why spend all the energy and why do you even have a job creating a brand?\n\nDoug Thielen (05:15): Yeah, that's a good question, and I don't know if I have the right answer or the perfect answer. I think the value of the brand is all the things that you don't see. It's the intangibles, it's the places that fill in the cracks. There's the product, and a lot of places have the same product or similar product, and you can use the best fibers, and yes, you can use the best materials that are available and stitch it in a way that no one else has. But I think the brand and what it stands for, the things you surround it with and where it comes from, the providence of that thing is what really pulls on people from an emotional perspective. It allows them to engage and interact with it.\n\nSpeaker 3 (05:50): It's\n\nDoug Thielen (05:50): One of the reasons you'll see at Filson. We have a ton of different events and experiences as a way to let people engage and interact with the brand to learn to experience, to dive deeper into be it an educational component or just a cool component, or to feel that they had a chance to be a part of something from conservation to education. And so for us, it's building all those different on-ramps to the brand\n\nCole Heilborn (06:15): And", "token_estimate": 522, "speakers": ["Doug Thielen", "Speaker 3", "Cole Heilborn"], "start_timestamp": "04:32", "end_timestamp": "06:15", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "52cb0041-8eb2-405c-b34d-df11ef955e2f", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 4, "content": "Doug Thielen (06:15): Finding ways for people to learn, to grow, to discover, and to find those different pieces that let them kind have a piece of them in it.\n\nCole Heilborn (06:25): Okay, interesting. So you mentioned an aspect of the brand. You mentioned the emotional part. Can you dive a little bit deeper into that? Why deal with emotion? What does that do?\n\nDoug Thielen (06:38): Yeah, I mean, I think we don't necessarily set out to say, let's touch on this emotion or let's find this thing and really bring it to the forefront as much as it is trying to show and highlight things we may not see up everywhere else. You mentioned wanting to talk about the Will to Live film that we recently did. (06:59): That's a piece that was a passion project that I got to work on with some really incredible people at FOS Media. Frankie and Adam over there were incredible. They were able to find a story and bring a story forward that I would say most brands wouldn't tell because it is a story for those who aren't familiar about a guy named Gary Edinger. He's written a book, which is phenomenal. So if you don't watch the film, read the book, either one or both, or both do both. And he's this incredible human who lived this life that read it was out of a fairytale champion dog sled racer, worked on fishing boats and was a trapper in Alaska. Comes back to Wisconsin where he's from, to be a logger, has a tragic accident where he loses his leg and he has to make a decision to pull himself back to the skidder from the skidder to his truck. (07:51): And then he drove himself out of the woods while on the phone with nine one one and made the decision to kind of fight to save his life and everything that happened out of that. That's a story that doesn't necessarily fit nicely into a box is an outdoor story. Is that an adventure story? Trust? It was like a human story. And so we look for those things. We look for those things that may not get always told or shown or featured or highlighted. We talk about harder or faster, tougher, meaner sometimes not as a joke, but a little bit of where is that going? Where are other brands necessarily not going to play, and how does that continue to evolve the story of Filsen?", "token_estimate": 557, "speakers": ["Doug Thielen", "Cole Heilborn"], "start_timestamp": "06:15", "end_timestamp": "06:38", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "b7459bdb-b8c2-46d8-8de1-df33f0a5e2c5", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 5, "content": "Cole Heilborn (08:27): Yeah, interesting. Okay. So there's a lot of things you just mentioned there that I feel like we could unpack for a long time. But diving a little bit further into the film, I know you guys have done a lot of other films in the past. What about film is something that you guys choose to invest in and to create?\n\nDoug Thielen (08:47): Yeah, that's a great question. I think we're still trying to figure it out. I mean, there's a lot of brands out there who've done phenomenal work in film for REIA place where I used to work does content. That's fantastic. Yeti obviously has done fantastic content, Patagonia as well. So I mean, I think we've got a ways to go before we're on the scale of what they're doing. That said, I think we've taken a chance on a few different things and have worked with a few different partners, and we've had to get creative with small budgets being a brand that isn't that size of those other ones I just mentioned.\n\nCole Heilborn (09:18): Sure.\n\nDoug Thielen (09:18): So for us, one of the things we're able to do is partner with different brands like Danner Footwear to go out to find a story to come together, and for us, finding a partner that makes sense so that the consumer, when they see that film and they see those two brands together, they don't kind of squint and wonder like\n\nCole Heilborn (09:34): What? Yeah, it makes\n\nDoug Thielen (09:35): Sense. Yeah. They go, well, of course Danner would work with Filson. That makes sense.\n\nCole Heilborn (09:39): Sure.", "token_estimate": 381, "speakers": ["Cole Heilborn", "Doug Thielen"], "start_timestamp": "08:27", "end_timestamp": "09:39", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "0aa05d3e-9b47-4ba0-8c13-a89d2f1401eb", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 6, "content": "Doug Thielen (09:41): So that was a key piece of finding a way to fund it. And then it was working with great storytellers and Adam and Frankie and that team over at FO to build something that we felt was going to be right for the story, right, for the brand. And then for us, it's taking a look at, and we do this with pretty much everything. We take a look at anything we invest in. It could be an event, it could be a product, it could be a partnership, a film, and squeezing every ounce of opportunity out of it. And so it's not just a film that we run online, it's a chance for our, put our brand in front of new people. So what's our distribution strategy and putting that film in front of the right audience? What's the event? What's the experience? Is it in store? Is it out of store? Are we partnering with a brewery to screen the film?\n\nSpeaker 3 (10:26): How\n\nDoug Thielen (10:26): Are we leveraging all those different pieces? How are we submitting it to film festivals once it gets accepted? How are we showing up and activating where I think sometimes it's easy to say, this thing is this thing. We made a film, we put it on YouTube,\n\nCole Heilborn (10:40): Leave it on the shelf\n\nDoug Thielen (10:41): Onto the next thing. I think one of the fun parts of being 120 year old startup being scrappy is you don't have that luxury where all of a sudden it's like, if we are going to spend this chunk of our budget making this thing or on this partnership, we've got to find every way to maximize that. What's the piece of content? What's the story? What's the social post? As a way to leverage all of that. I think a cool outcome of that is from a customer perspective, you're giving 'em a ton of on-ramps to discover it, to find it. It feels integrated. You're going a chance to go deeper If you want to go deeper, read a longer story, watch a bigger thing. And so those are reasons we look for films.", "token_estimate": 478, "speakers": ["Doug Thielen", "Speaker 3", "Cole Heilborn"], "start_timestamp": "09:41", "end_timestamp": "10:41", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "6056f46f-cc64-4837-8ad5-2336ad526f90", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 7, "content": "Cole Heilborn (11:20): So unfortunately, budgets are a very real thing. And so I know that you probably have to take, you look at an event or you look at a film and there's a budget associated with it. You have to take that to someone and I'm assuming get that signed off or it's part of your budget. How do you decide this film or this event or whatever you're trying to put on is worth the money?\n\nDoug Thielen (11:43): Yeah, that's a great question. I mean, to me, everything comes back to what's the objective? What's the objective for the company for the year, what's the objective for the department for the year? What's the objective for the channel for the year? And to me, it becomes very simple to say yes or no to or in terms of what's the priority. So if our objective is to put new eyeballs on Filson as a way to drive customer acquisition and an opportunity presents itself that doesn't help with that, it's quickly gets filtered out.\n\nCole Heilborn (12:13): Sure.\n\nDoug Thielen (12:14): It's also something where we take a look and say, okay, we have this much spend for the year and we're going to wait that opportunity, be it a film or an event, and look and say, okay, well this is what it costs. This is what it means by doing this. We no longer can do these other four things. Is everybody on board with that? Does everyone understand what that means by going through that? So it becomes relatively easy when it's all objective based and saying, okay, these were our goals. Does this help us get closer to it?\n\nCole Heilborn (12:42): I see.\n\nDoug Thielen (12:43): Or does this detract from it?\n\nCole Heilborn (12:45): Yeah. So what did you find from doing that film? It's been out for a while. I think you guys are up to how many views on Facebook or in YouTube now?", "token_estimate": 447, "speakers": ["Cole Heilborn", "Doug Thielen"], "start_timestamp": "11:20", "end_timestamp": "12:45", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "d3a4795c-7045-483e-b74d-7df437c5778f", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 8, "content": "Doug Thielen (12:52): So on YouTube, I think we've pressed like 208,000 views on our channel. I haven't looked at Danner ran it as well. I know back in November when you looked at Danner's, Facebook and YouTube and our Facebook and YouTube, we were well over a million views. We ran a targeted campaign too from a distribution perspective targeted towards new audiences. So we're using that as a way to bring people into the fills and\n\nCole Heilborn (13:17): Fold.\n\nDoug Thielen (13:18): We also ran multiple screenings. So we did a screening here in Seattle screen in event Oregon screen in Portland, Oregon as a way to have an event and bring people together. We had Gary and the FOSS team out here in Seattle. We had Gary and the FOSS team at Ben. One of the more interesting events is we ran one in Portland at a brewery, straight screening. People could watch the exact same film on YouTube or they could come out to Rogue Brewing and have an evening with us and Danner. But we brought in a nonprofit back country, hunters and Anglers, a group that we work with quite a bit from a public land and access perspective, and we used it as a fundraising event. So Danner put in a great giveaway. We had a great giveaway. Rogue, I think it was a percent of sales that night, all went back to BHA standing room. Only packed house had to turn people away, which I love. That's people who want to engage with the community, meet other people, get outside of their home and watch a film again, they could watch online. To me, that's telling that there's a hunger within that community to get together. So we're continuing to do screens in the east coast. We've done 'em in Detroit and New York. I think we have one in Boston coming up, (14:30): Some in store as a way to drive store traffic, others at breweries and other locations as a way to, you want to have the man of the woman sitting there drinking a beer. They look over and say, well, what is that thing that's playing? So it's an easy kind of low key way to introduce the brand and film new folks.", "token_estimate": 513, "speakers": ["Doug Thielen", "Cole Heilborn"], "start_timestamp": "12:52", "end_timestamp": "13:18", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "23699f08-70a9-4fdb-921b-007a04debc2c", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 9, "content": "Cole Heilborn (14:49): Sure, sure. Have you guys a chance to kind of come full circle, circle the wagons and analyze any metrics from the film? Have you collected those or is that still, I mean, the film is still kind running.\n\nDoug Thielen (15:01): Yeah, the film's still running. So the wonderful part, I guess, of running the distribution campaign through Google is all the analytics and metrics is able to get you, so you're able to see, while we were optimizing that campaign for views, we were able to see click through rates as well as return on ad spend from that. So it's positive to be able to see and go, yes, not only did we make a film that yes can attract new customers, yes, people are watching 80, 90, a hundred percent of the way through, but it's also driving clicks to the website and it's also driving sales. So from a metrics perspective, that's a great story to package and tell leadership and say, yeah, this thing, yes, it cost us money, but it also made us money definitively through this channel. And so those are things that help get more films, more projects funded.\n\nCole Heilborn (15:48): Yeah, makes sense.\n\nDoug Thielen (15:50): Yeah.\n\nCole Heilborn (15:50): So transitioning a little bit, what is Filson's biggest challenge? What are you guys working on? That's,\n\nDoug Thielen (15:59): That's a great question. I mean, I think we face the same challenge that a lot of brands and businesses face that have retail locations is how do you grow retail while at the same time facing the ever present wave of online and online retailers direct to consumers who don't have retail at all or don't have\n\nSpeaker 3 (16:18): Wholesale.", "token_estimate": 415, "speakers": ["Cole Heilborn", "Doug Thielen", "Speaker 3"], "start_timestamp": "14:49", "end_timestamp": "16:18", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "57174f9d-39ae-4777-8d51-fcabbca8a894", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 10, "content": "Doug Thielen (16:19): How do we continue to develop product in a way that's innovative and true to the brand? How do you do those pieces while at the same time growing and hitting the growth rates that people want us to hit? (16:34): I think it's a good challenge. We definitely have, I mentioned that the mentality of being 120 year old startup, and it really feels that way. It feels everyone who is here has come in and has invested in the company. They really want to see this thing work. It's all hustle. It's pretty fun. I think it either attracts, I've used the analogy before when talking to new hires, potential hires that here it filson. If you see a leak in the roof, be careful to point it out because someone will hand you a hammer and a shingle and say, fix it. Go. I tell that to people and that either attracts them and gets them really excited about the opportunity that lies ahead, or it scares the shit out of 'em, and they're like, yeah, not for me. That's fine. That's not a bad thing. But I think the brand and the life cycle and growth cycle of where we are today, it's interesting to see us push on the elasticity of the brand and what we can do and where it can go. And good ideas have come from anywhere, and you have a chance to work on a lot of different things here.\n\nCole Heilborn (17:33): So I guess in the outdoor retail space, there's a lot of manufacturers making a lot of different types of products, some of 'em not so different. Where do you guys see yourself fitting into that market? Because in today's age of Gore-Tex and whatever the next fabric is, you have a much different approach to your manufacturing methods and the materials you use. Where do you fit into that?", "token_estimate": 428, "speakers": ["Doug Thielen", "Cole Heilborn"], "start_timestamp": "16:19", "end_timestamp": "17:33", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "933b4a9d-d79e-45ad-9b57-a1a8bb383be1", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 11, "content": "Doug Thielen (17:59): That's a good question. It's probably better answered by our product development team who spends their nights, days, weekends, every week, hour, thinking about how to do that. I think from a marketing perspective, what's really fun is the dynamism of the brand. We've got our Mackinac wool cruiser, which is made the same way with the same material as it was when it was patented in 1914, hanging next to a technical rainwear product that is using some of the best fabric and best products and materials that you can get, and what other brands really going to be able to play in that zone. There are by no means, I think we're the only one, but that's a pretty unique thing to be able to pull on something that has history, that has providence, that's been around a long time, that's still warrants itself and is useful in the outdoor industry. But then we have things that are technical that are solving problems for our customers that we're able to create, develop, and give them so that they have that need met.\n\nCole Heilborn (18:59): Yeah, interesting. What do you enjoy doing in the outdoors? What's your go-to?\n\nDoug Thielen (19:04): Oh, man. If it's wintertime, you find me skiing. That's literally where I spend every time that I can. I've got two kiddos, which makes it a little more challenging now, but now we just got them on skis. The youngest turned two early December, and she was on skis the first time on her birthday.\n\nCole Heilborn (19:20): Oh man.\n\nDoug Thielen (19:20): And then the 5-year-old, she is a ski machine. She goes everywhere with me, we're Whistler. She's skiing at all. And if I would let her, she'd go even further and harder. So that's fun. And then the summertime mountain biking, which was a sport that I did for a while, kind of stepped away from, did road biking and triathlon for a long time. And then when I moved back to the northwest in 2014, just rediscovered mountain biking and the muddy messiness. That's super fun. And I really haven't, I think I've touched my road bike two times in the last five years. I always just spend all that time on the mountain bike.", "token_estimate": 533, "speakers": ["Doug Thielen", "Cole Heilborn"], "start_timestamp": "17:59", "end_timestamp": "19:20", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "c0846b94-0182-4685-aa03-83ec2796a962", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 12, "content": "Cole Heilborn (19:52): Yeah, nice. Well, there's definitely no shortage of outdoor opportunities here.\n\nDoug Thielen (19:57): No, absolutely not.\n\nCole Heilborn (19:59): As you look forward towards marketing in the future, there's obviously a whole new wave of people that are moving in and taking marketing positions. What do you see, if you could say anything to the people that are stepping into it that are learning it, what do you think is, what's the takeaway? What should they consider as they're trying to figure out how to do this themselves?\n\nDoug Thielen (20:20): Yeah, that's a great question. I think people and brands that have the ability to blend content and commerce and see them not as separate things, but see them as one, see them through the customer's eyes are going to win, be their brand or a person. I think the days of seeing things so separate, oh, I do. Oh, I do creative. I tell stories. I sell things. It's not how the customers look at\n\nSpeaker 3 (20:44): It.", "token_estimate": 248, "speakers": ["Cole Heilborn", "Doug Thielen", "Speaker 3"], "start_timestamp": "19:52", "end_timestamp": "20:44", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "9345838b-7b69-4585-a56a-a689157ecdfc", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 13, "content": "Doug Thielen (20:44): And the more brands and people do to marry those two things, and I'm referred to it as story selling instead of storytelling, there's a piece to it at all points of that funnel where you're meeting that customer. But by no means are we doing it perfect. We have a long way to go to get to where I want to see SB. But when you have that ability to provide value to the customer, so if you come in and buy a fishing jacket and you get an email saying, Hey, here's your order. It's confirmed. It's on its way. I don't want to send you an email that has another buy now piece into it. I want to send you an email that has a story about fishing. Come watch the film (21:22): On the life of a guide. Come read a story on how to take care of your jacket, come read or view this trip, this photo tour this guy took down in Texas. That was crazy. I want to provide content that adds value to your experience. On the other side of that one, someone's engaging with a film or a story on the fill some journal. I want to be able to drive them to product that's relevant to the story that they're reading in a way that adds value. They read a great fishing story, they read a great hunting story. Now let's take them to product and information that allows them to dive a little deeper. If they see an image on the story, they're like, ah, that's a great jacket she wearing. Well, we should make it easy for them to find it.\n\nSpeaker 3 (22:03): Right?\n\nDoug Thielen (22:04): So that blend of content and commerce, I think is something that people can bring to the table. Adding a layer of creativity to the numbers and adding numbers to creativity and not being scared to do so, knowing from a numbers side, not everything is black and white. There is some gray. Sometimes. We have to make that gray decision and knowing it's that not being held to the numbers on creative side, but being aware of the metrics, being aware of what's going on, letting that make you a better creative.", "token_estimate": 498, "speakers": ["Doug Thielen", "Speaker 3"], "start_timestamp": "20:44", "end_timestamp": "22:04", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "beddd966-648d-455d-a568-f09c41b4202c", "episode_id": "68a481d6-21cc-4574-b7b8-49cf8998141e", "cms_item_id": "68225dfc7bb476527f8c482f", "chunk_index": 14, "content": "Cole Heilborn (22:32): Yeah. Well, that's awesome. There's so much information there that I feel like you could unpack, and I mean with any career, it takes a lifetime to figure this stuff out and sort through it, and so it's been really great to chat with you. I'm afraid we're about out of time.\n\nDoug Thielen (22:47): Okay.\n\nCole Heilborn (22:47): If people want to find Filson, where can they find you? Where can they find the film?\n\nDoug Thielen (22:53): Yeah, absolutely. I encourage you to go to filson.com/blog to see all of our content. The Filson Journal has been redone and updated with tremendous amount of content. The film is there, all of our films will we found there. You can also find the films on YouTube naturally, and then filson.com in general where you'll see all of our new product that we continue to develop and release there.\n\nCole Heilborn (23:12): Awesome. Well, thank you so much, Doug. Absolutely. I appreciate it.\n\nDoug Thielen (23:15): Yeah.\n\nCole Heilborn (23:16): Yeah. Have a good day.\n\nDoug Thielen (23:17): Thanks, you too.\n\nCole Heilborn (23:17): Take care. Appreciate\n\nDoug Thielen (23:18): It.", "token_estimate": 284, "speakers": ["Cole Heilborn", "Doug Thielen"], "start_timestamp": "22:32", "end_timestamp": "23:18", "podcast_index": 4, "episode_name": "Ep 4: Doug Thielen | The 120 year old startup | Filson", "slug": "doug-thielen-the-120-year-old-startup-filson", "web_url": "https://www.portsidepro.com/podcast-feed/doug-thielen-the-120-year-old-startup-filson", "guest_name": "Dough Thielen", "guest_title": "Filson", "categories": [], "short_description": "In this episode, I sit down and chat with Doug Thielen, the marketing director about the challenges and opportunities of working with a brand that was started in 1897. We chat about their history, but also how they are using branded films to continue the Filson legacy.", "podcast_length": "44:26"}, {"id": "61f259c2-ecad-4a48-b4bb-ee2225ffb7cd", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 0, "content": "Peter Williams (00:04): It is about getting outside and getting our kids outside and being able to live busy kind of urban lives without having a sacrifice of connection to the outdoors and that sort of spontaneous, youthful spirit that is a little bit harder to hold onto as your life gets more complex and the responsibilities pack up.\n\nCole Heilborn (00:27): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Hallborn. Today I'm sitting down with Peter Williams and Spencer Hauser, the two co-founders, two of the three co-founders rather of Super Pacific gentlemen. How are you guys doing?\n\nSpencer Houser (01:12): Good. Yeah. Yeah, we're doing good. We are super busy and really psyched to be talking to you.\n\nCole Heilborn (01:19): Yeah, thanks for taking time out of your busy day, it sounds like. Well, just based on the conversation 20 seconds earlier, it sounds like you guys are pretty slammed. So yeah, thanks for making the time.\n\nPeter Williams (01:31): Yeah, absolutely. Looking forward to it. Yep.\n\nSpencer Houser (01:33): Yeah, thank you.\n\nCole Heilborn (01:35): So you guys are down in the Portland area, is that right?\n\nPeter Williams (01:38): We are. We're in Northeast Portland. Yep.", "token_estimate": 446, "speakers": ["Peter Williams", "Cole Heilborn", "Spencer Houser"], "start_timestamp": "00:04", "end_timestamp": "01:38", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "77d73b02-9302-4007-8067-bfb153b3f54c", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 1, "content": "Cole Heilborn (01:40): Okay. I'm super excited to chat with you guys today. I'm stoked to kind of hear a little bit about what you guys are up to. I've been seeing your name popping up over the interweb the last couple months. I'm assuming that's because you guys are doing something pretty cool and pretty rad, but fill us in what is super Pacific. What's this project you guys have undertaken and is now consuming most of your lives?\n\nPeter Williams (02:05): So I can give you the quick and dirty history to date if you want. And Spencer and I worked together at a design consultancy in past lives, and when we left that job, we stayed in touch and maintained a friendship. And I have a five-year-old son, and as my life's transitioned from not being a parent to being a parent, I realized it became a lot more complex to get outdoors and started looking at how to make that easier. So I started looking at, do we want to do a conversion van? Do we want to get a slide in camper? What's our best adventure vehicle? And my life had some constraints. There's not great off street parking at my house, and we're kind of thinking about it with an eye on the budget and all those kind of real world constraints. So I started the pop-up camper market and got really interested in it and was just over at Spencer's one afternoon, two summers ago now having a beer and looking at 'em and was like, these are cool. These are looking sweet. There's a couple things I would do different about this one. I'd do that one a little bit different. And we were just over a beer. We're like, well, let's just make, you've got the metal skills, I've got the fabric skills. Let's make one just like we want it. These are sweet. We'll make one for your truck, one for mine, and that'll be fun. What a cool thing to do. (03:30): And that led into really digging into the design, looking at the designs real closely and really studying the decisions that everyone had made and looking at some feedback and reviews, just trying to educate our point of view on what we wanted to do, which in the process of that we started seeing a lot of back orders and it felt like there was an undersupply for a pretty big demand. And we then started doing some market research and sort of realized we were looking at what might be a business opportunity. And at that point we had breaks on our fund side project and started thinking about is this something we could build a business around? And now whatever it is, a year and a half later, here we are up and running and trying to keep up.", "token_estimate": 639, "speakers": ["Cole Heilborn", "Peter Williams"], "start_timestamp": "01:40", "end_timestamp": "02:05", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "2e6f8d94-5e5d-4e6c-9f2c-12af278e81bd", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 2, "content": "Spencer Houser (04:14): Yeah, definitely. Yeah, whenever I look at a project, I've got a background in design and manufacturing, kind of heavy in both. And whenever I look to build something, I've always got it in the back of my head, what if I was going to build more than one of these things? And so it was a relatively simple exercise for us because as we thought about this, it was like, well, this is going to be cool. Pizza's going to be cool, mine's going to be cool. I'm sure one of my friends is going to want one of these. And then I also have a background in, I own my own business. I own a machine shop and a Ducati motorcycle parts brand for about 15 years in the machine shop, 10 years on the parts side. So it's always in the back of my mind, is there some opportunity here if I'm building something, is there some opportunity to either make more, sell a few more or build a business out of it? And it seemed like there was quite a bit of opportunity based on the market research as we really got into these things. And thus Pete and I started thinking about this more of, let's see what we can start, see what we can do.\n\nCole Heilborn (05:26): Unfortunately, this is just an audio format, folks can't actually see what we're talking about right now, but if you go over to the Super Pacific website, take a look, what we're talking about is these awesome rooftop camper sleepers, and I'll let you guys maybe describe them. I think you obviously you're going to do a better job than I will, but they're pretty slick looking and it looks like they've been designed with some pretty key features and components. Can you kind of break down some of the design choices you guys have made? And you've got two models, right? Or two different styles?", "token_estimate": 440, "speakers": ["Spencer Houser", "Cole Heilborn"], "start_timestamp": "04:14", "end_timestamp": "05:26", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "b69df8de-ebe0-4070-8b82-f9fd200e1096", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 3, "content": "Peter Williams (06:01): Yeah, essentially we have the broadstrokes of our design intent was that we both own pickup trucks and use them daily, use them as pickup trucks regularly in our normal life. And we both really put a premium on spending time outdoors, especially getting our kids out and our families out. So we wanted something that would facilitate that kind of outdoor lifestyle without compromising the utility of our pickups. So we wanted something basically that was going to be a camper shell, just a canopy over the truck bed that weekdays you've got an empty truck bed, a dry empty truck bed, and then on Friday you can just throw a cooler in your kitchen in there and you're set. So really trying to streamline the whole transition from work truck to adventure truck. (06:50): So that's the broad stroke stroke sort of functionally of what we did. Then from there, we just looked at, we have a pretty good sense of what we want to do with them, but they're really useful for anyone that wants to go outside, regardless of what they do. If they're driving to the place outdoors that they want to go do that thing and they plan on spending the night, then this is a super useful piece of equipment. So towards that end, we figured we would try to do a really good job on about 90% of the build and then just set the people up, set everyone up to really finish the build easily and get it tuned into exactly what they want it to be. So even we've designed it with an eye for customization and trying to facilitate people's process of tuning it in, if they want to build out a kitchen and have it all dedicated to camping full time that we've got wire chases and threaded bosses and lash points all throughout it, and if they have a different intent, then it should be easy to bolt stuff to it and strap stuff onto it. (07:51): And I really get it dialed.", "token_estimate": 467, "speakers": ["Peter Williams"], "start_timestamp": "06:01", "end_timestamp": "06:01", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "e1cf50a5-8395-43e6-8e74-11983d34135f", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 4, "content": "Spencer Houser (07:53): And I think one of the things Pete didn't say as we described this to people who are not seeing it, so we've got the hard shell canopy, the traditional canopy, and then on top of that we've got a wedge-shaped tent. The wed shaped tent can also be used as kind of a standalone unit. So you can take that wedge-shaped tent without the canopy and put it on your Toyota for runner or your kind of SUV off-road, SUV, and still be able to just use it as a standalone tent, very low profile. One of the features of this is trying to have as little impact on your vehicle as possible. So making it lightweight, making it super low profile, making it so it's not like the standard kind of tent that you see on a Subaru or something, which is a box that has a lot of straps and a cloth cover and that kind of thing. We try to make it all hard. Shell very robust, the kind of thing that when you're not camping, you can throw sheets of plywood on it or two by fours or surfboards or mountain bikes or whatever it is, and drive down the road with very little impact to your daily driver kind of thing. So\n\nCole Heilborn (09:14): That's awesome. Don't know how many, I think everyone who has a truck wants to use it for multiple purposes. That's the reason why you get a truck is because you want to be able to do a dump run and you want to be able to camp out of it. But if you have to go through this lengthy process of converting it between usage, it just makes it tougher to use.\n\nPeter Williams (09:34): Yeah, that's exactly right. Yep.\n\nCole Heilborn (09:36): Yep. So I feel like the rooftop tents are definitely hot right now. There's a number of different brands that are making them. I'm curious though, I mean you guys have only been around for how long now?\n\nPeter Williams (09:50): We've been selling, I guess we went live in terms of selling to people five months ago.", "token_estimate": 473, "speakers": ["Spencer Houser", "Cole Heilborn", "Peter Williams"], "start_timestamp": "07:53", "end_timestamp": "09:50", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "2951837f-059e-4373-a2f0-e69b46f80d47", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 5, "content": "Spencer Houser (09:56): Basically about July 1st is when our website went live. We'd actually been relatively, we started thinking about that a year previous thinking about the company, your previous, we got real serious about a year ago last fall, and we actually incorporated in, it's almost a year, December 12th last year. So when we officially formed a company, but we had been actively prototyping parts from about September, September on from last year. So it was roughly a year of development before we launched the website and started trying to generate some pre-orders on some of our stuff.\n\nCole Heilborn (10:42): So needless to say, pretty new into it. You guys are pretty early into your first production runs. I guess, why did you decide to jump into this? I mean, you're kind of going up against some of the big brands in the space. I'm thinking recently about tle just recently purchased the Pui brand, and obviously Tulle is a massive international company, and here you guys are just charging into the space. So I guess I'm curious why and how. Yeah.", "token_estimate": 267, "speakers": ["Spencer Houser", "Cole Heilborn"], "start_timestamp": "09:56", "end_timestamp": "10:42", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "c2ff029d-c129-435d-bf14-a831205b8fa7", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 6, "content": "Peter Williams (11:15): Yeah, Cole, I totally agree. I think so. I think we are operating in the small kind of niche within the larger space. So there's rooftop, tints are a category, and then there's sort of campers, which are a category and what we're doing, there's a couple other companies out there that are making a similar product that is this really, I call it a low impact camper on your pickup. And that niche I think is a tough one for those bigger brands to fill. But the rooftop space, I agree with you, is very competitive. There are a lot of people competing in it, and we have seen, we've sold a lot of our integrated truck shell camper and a few are rooftop tents, standalone rooftop tents. So we're kind of on feel that out, and if it makes sense for us to continue doing the rooftop tint, then we will. And if it feels like we're competing, we're not really competing on price in that market, we're competing on value. And I feel confident we're bringing a superior product to a lot of the competition to the market. I just don't know if enough people are going to want to pay the premium when there's plenty of imported options that are significantly cheaper. So (12:35): That piece, we're kind of watching and we're going to figure that out. But the integrated truck bed camper, that one, we feel confident about that. I think it would be. Yeah, I think we're, we're going to run that down and see what we can do with it.", "token_estimate": 361, "speakers": ["Peter Williams"], "start_timestamp": "11:15", "end_timestamp": "11:15", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "e20bed6b-d54b-46bb-b904-affcc34372c3", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 7, "content": "Spencer Houser (12:49): Yeah, I think we've risen pretty fast to be a player in that marketplace. There's probably four or five other companies that are doing what we're doing. And as with our backgrounds, as we looked at everything that was available within those four or five other brands, I mean, we did a lot of research looking at forums, looking at articles, talking to people, finding out what they liked and disliked about the brands that were out there and generated this pros and cons list and thought, well, we could probably build something that encompass a lot of these pros on this list. And Pete and I, because of our backgrounds have a way different approach to the way product is built and the way product is designed, and we thought we could probably make a mark because we could bring something that was new, innovative and different to this kind of small niche market that we're in now.\n\nCole Heilborn (14:00): Yeah, yeah. Dive a little deeper into that niche market, not necessarily in the hardcore overlanding world, and you're not in the camping RV camper world, you're kind of straddling the two, but also defining your own. It sounds like that was pretty intentional in terms of where you wanted to go considering just your own personal backgrounds and needs.", "token_estimate": 321, "speakers": ["Spencer Houser", "Cole Heilborn"], "start_timestamp": "12:49", "end_timestamp": "14:00", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "b13cd88a-cc62-40a6-bea1-01c2f873f6d4", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 8, "content": "Peter Williams (14:23): Yeah, I mean, the truth is we saw that opportunity because that was the reality that was solving a problem that existed in our personal realities. And like I said, we both have pickups, we both use them as pickups more often than we use them as campers, and we really value the outdoor recreation as part of the lifestyle and part of raising our families. So as we looked into it, it just kept looking like the market research we were doing, we kind of looked into how people were reporting that they used the products that they did buy, and it looked like there were a lot of people who were in a similar situation to us where their aspirations are certainly to spend as much time outside as they can, but the problem they're trying to solve is not necessarily to live out of the truck or to go drive across the continent, although if you chose to outfit this thing to do that, it would certainly support that we're building a product that can support that kind of objective, but that's not necessarily the use case that we designed it for.\n\nCole Heilborn (15:30): Tell me a little bit more about that market research. How did you conduct that? Did you have any expectations or ideas going into it? And what did you find?\n\nPeter Williams (15:41): We looked through, there's a big trade show called the, what is it? The Overland Expo?\n\nSpencer Houser (15:49): Yeah, Overland Expo.\n\nPeter Williams (15:50): And they do quite a bit of research and they make it public. So we looked through that and there are a lot of public market research that's been done by, Coleman had a big report on camping, and we looked into those different publications, I guess you'd call 'em, or the data that we could find out there. And then we also did a bit of just looking, just observing the market and talking to people that we ran into that had products that we were interested in and that we felt like were in the right niche, getting a sense of what they liked about 'em, what they used them for. And yeah, there was quite a bit of information out there once we started looking for it, but I would say it was 90% desk work, 10% seeking people out and talking to 'em.", "token_estimate": 545, "speakers": ["Peter Williams", "Cole Heilborn", "Spencer Houser"], "start_timestamp": "14:23", "end_timestamp": "15:50", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "7ea9d49c-e40a-4331-82cb-845b33f8189b", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 9, "content": "Spencer Houser (16:38): Yeah. Yeah. I think we started with the Overland Journal, Overland Expo people. They've got some really good stats, but that led us into, like Pete said, the Coleman big Coleman report. I think we started in the kind of the overland world, but it led us into the bigger outdoor recreation world. And outdoor recreation is a massive, massive market as a percent of GDP. It's actually bigger than energy (17:17): In the United States, and on the order of hundreds of billions of dollars a year. And as we did our research, we realized that a lot of maybe our competitors are looking at very specifically the marketplace, but as we looked at it, we thought that maybe there's a lot more opportunity as an outdoor company. We are definitely entering here in this kind of overlanding world. But what we're trying to approach it as is more of an outdoor point of view. Everybody aspires to have the gear and the lifestyle that you drive across Siberia and then you climb a huge mountain and every day is the best Instagram day you've ever had. The reality is is that most families, I think, are lucky to get out six or eight times a summer and you're using your pickup for a variety of things. And we wanted to build a product that met the reality of what families do, yet was robust enough and the serious, hardcore outdoor or overlanding enthusiast could look at our product and go, oh, yeah, I could live out of this for the guys that can't 120 days a year and build their stuff out. (19:06): They could look at our stuff and go, yep, this is going to hold up great. But for the suburban mom and dad and Pete with a five-year-old could look at it and go, oh, well that's really approachable. This will support what we want to do, and I'm still going to be able to go to Home Depot and haul yard debris. (19:30): People like to customize things, whether it's your mountain bike, whether it's your fishing pole, your camping gear, your kayaking stuff. People like to customize their stuff. And as we looked at what was out there, it kind of felt like it was an opportunity that the other companies were missing is that if we built something like Pete was saying with wire chases, with threaded bosses, with hook points, with T slots, that gave people the opportunity to build and to customize and to add things, we'd be setting ourselves apart and offering something that everybody else kind of was overlooking. And so we integrated that into our design from the get go, and it's proving to be pretty popular.", "token_estimate": 632, "speakers": ["Spencer Houser"], "start_timestamp": "16:38", "end_timestamp": "16:38", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "c08ad5b4-60f6-4216-acfc-3c2eb7e1ddc7", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 10, "content": "Cole Heilborn (20:28): So where are you guys? You're about a year old, you said it's been the last few months now you've been producing product and working through the production challenges. Where are you in your product line in terms of distribution? What are things looking like for this last year and looking for this next year?\n\nPeter Williams (20:50): So basically we sort of built our business model and growth model based on what we felt were somewhat optimistic projections and had a plan of scaling up slowly over the course of several months. But as it's materialized, we have sold way faster than we expected. So we've been having to build up our throughput and our systems a lot sooner than we thought. And we've also had to do it a lot earlier in the life of the business than we expected. So it is definitely been full on. We have now got five employees, not including Josh Spencer and myself, who are all now. And yeah, we're ramping up. Every build cycle goes smoother and we're able to work more efficiently.", "token_estimate": 257, "speakers": ["Cole Heilborn", "Peter Williams"], "start_timestamp": "20:28", "end_timestamp": "20:50", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "91aa0598-a299-4bf2-ae47-843c7e50988e", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 11, "content": "Spencer Houser (21:47): I've got quite a bit of background in manufacturing. I owned a machine shop for 15 years. Like I said before, I was an operations manager for an aerospace manufacturer for about three and a half years. I helped that company basically ramp itself up pretty significantly. I've helped build out factories and have a background in lean manufacturing and things like that. So as we looked at this company and our products, we designed it around the idea that we could scale this thing up from a manufacturing standpoint, made sure that the products were unique, the individual components were unique, but it was stuff that you could manufacture. We weren't going to have to invent an anti-gravity machine in order for our product to work. So we had this great game plan, and like Pete said, we had this nice little ramp up. We were going to sell four a month the first month and six the second month, and it was going to be great. We could build the shop out nights and slowly hire one or two employees, get everybody trained, and we completely underestimated the demand. And I think COVID has a lot to do with that. I think if we'd just gone our original, if there was no COVID, it would've run closer though, probably more than what we had originally anticipated. (23:18): So we've had to scramble because I figured that I would be the guy building things full time for the first month, and after three months we'd hire an employee. And within that first three weeks, it was like, holy crap, we got to hire our first employee tomorrow. And I think the game plan too, Pete had a full-time job originally, and we thought maybe after six months or so we could start talking about Pete coming on full time. And within two months I was coming to him and saying, dude, I think you need to quit your job and you need to come do this full time, which it is a big deal to ask somebody to do that, especially when they have a very good comfortable job. (24:09): So our challenges these days have just been, everything's going faster than we anticipated. The upside is that I think we all very much understand what we're doing. And our first hire was a guy who had worked for me before who was like an ACE assembly guy. Our second hire was, again, a person that I'd worked with in the past who was a scheduler planner, a trained scheduler planner, which is something that's huge in aerospace and in manufacturing. We've been setting up our foundation for success, but the demand has been just wildly off the charts. So I think for both Pete and I, in one sense, things aren't going the way we want it to because nothing's happening fast enough and we're just kind of overwhelmed all the time. The flip side of that, this is all really good stuff. There's nothing that you should shake a stick at because it looks like chances are this company is going to, unless we make some really big mistake, it is going to be a successful company and we are going to be able to do everything that we want to do. It's just taken a while to get going by early this year, February or March, we should be able to finish one camper a day, so we should be on track for that. (25:47): The foundation is in place for that, and things are looking good on that side, but it is a bit of a slog to get to that point. And once we get to that one a day kind of number, we should be able to basically scale it, duplicate it, and in a relatively short amount of time, get to two campers a day and that kind of thing.", "token_estimate": 875, "speakers": ["Spencer Houser"], "start_timestamp": "21:47", "end_timestamp": "21:47", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "67c3a952-9b66-4196-996d-2d2d5fe200fd", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 12, "content": "Cole Heilborn (26:16): So you'd mentioned that your projection the first month was to build four campers or to sell four campers. What did the first month end up being?\n\nSpencer Houser (26:25): 10, I think.\n\nCole Heilborn (26:27): Oh, wow.\n\nSpencer Houser (26:30): 10 or 15. I know in one, I just had Cindy, she's our scheduler. Kind of look through those numbers and help me scale it. I think one we sold 40 a couple of months ago, two months ago,\n\nCole Heilborn (26:51): That explains the frantic new hires.\n\nSpencer Houser (26:54): Yeah. Oh yeah. And again, thinking you're going to sell four to six a month and then selling 40, I mean, that wasn't even on our charts.\n\nCole Heilborn (27:03): So other than COVID, I mean obviously COVID has pushed a bunch of people outside and has probably contributed a little bit, like you said to the recent sales increases. You guys are just getting into this. You're obviously not, I'm assuming spending a whole bunch of time thinking about your marketing and spending a lot of time doing that because still frantically trying to crank out product and meet the demand. I guess, where do you think the interest has come? How have people heard about you? What are you looking to do in 2021 to kind of further keep that snowball moving?", "token_estimate": 319, "speakers": ["Cole Heilborn", "Spencer Houser"], "start_timestamp": "26:16", "end_timestamp": "27:03", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "6b0267c0-57f9-4b82-8834-4a1358ded8e9", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 13, "content": "Peter Williams (27:44): Sure. Well, I think the way people have heard about us to date is really through Instagram. There've been a couple of people that couple of our early customers had a decent Instagram following, and I think that brought some attention to us for sure. But then it's just been organic. All we've done is put stuff on Instagram and the growth has been organic and the sales have really been organic as well to date. So we're actually going out this weekend to do our first, if you look at our website, it's all renderings. We built the website before we had any production units to take photographs of. So we're going out this weekend to actually do our first round of generating any sort of intentional content that we'll use on our website and start building out some marketing material with. But yeah, as we move forward, Josh is going to be leading the charge on our marketing. He came on, his expertise is in graphic design and branding. So marketing is different than branding, and we're all kind of figuring out how to approach it, kind of live here together.\n\nSpencer Houser (29:07): But if I can interject, I think marketing though is a lot closer to Josh's level. What Josh is an expert at for\n\nPeter Williams (29:15): Sure.\n\nSpencer Houser (29:17): Pete's expertise is soft goods and usage. My expertise is hard goods and the operation side of things. So Josh, taking over that marketing aspect is, like I said, it's way closer to what he knows than what Pete, and I know\n\nPeter Williams (29:40): He's definitely worked tightly with marketing teams before, whereas I know that I haven't, and I don't know if you have Spencer, but yeah. So all this to say, none of us have made a year marketing plan before or anything like that. Kind of starting to map that out and get a, we're going to be learning as we go essentially.", "token_estimate": 463, "speakers": ["Peter Williams", "Spencer Houser"], "start_timestamp": "27:44", "end_timestamp": "29:40", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "c014d64b-5106-4853-90b9-2af0b25493ef", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 14, "content": "Spencer Houser (30:01): That said, we did early on, we did connect with a branding and marketing company, a small consultancy here who's got very, very deep connections in the outdoor industry, and they walked us through, we built a deck that identifies our key consumers and identifies the markets we're going after and things like that. And I think that's helped to Josh to kind of focus on certain things as we're doing Instagram posts and things like that. And we've had a lot of, we've been lucky in that we had a number of, I think kind of key influencers and things notice us early on, and we've been able to make some pretty good connections through 'em next year. I think the idea is we're going to hit all the overland expos that we can and hit the regional, there's some regional expo, or not expos, but\n\nPeter Williams (31:19): Events,\n\nSpencer Houser (31:20): The Northwest Overland Valley and things like that. That was part of our original pre COVID game plan. And so we'll kind of kick that into gear this year and then try to hit or try to begin some advertising on some websites and things like that. But frankly, to be perfectly honest, putting a bunch of effort into advertising at this point kind of scares me because one of the reasons we started this company is we saw that everybody had these year, 18 month long back orders, and we don't want to be that company. I would love it if a customer can call us up and could buy product right off the shelf from us. And we are pushing the six month lead time right now, and that's driving me nuts. And the reality is we can't scale fast enough to meet this demand, but we're trying and we're doing our best. So yeah, like I said, it's a little scary to think of advertising and think of all of a sudden all these more eyes on us hardly keeping up with what we got with the orders that have been placed.", "token_estimate": 468, "speakers": ["Spencer Houser", "Peter Williams"], "start_timestamp": "30:01", "end_timestamp": "31:20", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "e724b2b3-3e1e-42f2-9d1d-3a784ad4761a", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 15, "content": "Peter Williams (32:55): Yeah, sales have not been our challenge so far, but as we build a bigger engine, we need to keep feeding it. And I am very excited about the marketing side. I think it's going to be a really interesting thing to figure out. And I think that the work of it looks like it will be fun. So I'm excited to get into it. And we do have to, we can't really take our blinders off still building this engine, but as we get going, I'm real stoked to start defining what Super Pacific is.\n\nCole Heilborn (33:32): Yeah, I mean, you guys were just in the early frantic stage of trying to make it all come together. And marketing is, I feel like it's one of those things, one of those luxuries you can think about. Once you have that base and you have that process and that foundation built, and then you can start to, instead of looking behind you all the time, you can start to look forwards and be like, okay, let's start to plan for the future and how does everything fit together where we want to be a year from now. But I think what's rad is the outdoor industry is made up of at some point in time, all the businesses, all the big brands that we all look at as kind of the giants or the leaders, they all started at some point just like where you guys are at trying to crank out your campers and not get too far behind and just try to keep up with the demand. And I just think that's cool to see and get a glimpse of where you guys are at in your process.\n\nSpencer Houser (34:29): Yeah, these are exciting. Let's use the word exciting. These are exciting times right now. Yeah,\n\nCole Heilborn (34:38): There you go. Where do you want the company to go?\n\nSpencer Houser (34:43): That's a good question. World domination, pretty much complete world domination is\n\nCole Heilborn (34:49): Every pickup has a super Pacific rig on it, new\n\nSpencer Houser (34:53): And old, all of them.", "token_estimate": 474, "speakers": ["Peter Williams", "Cole Heilborn", "Spencer Houser"], "start_timestamp": "32:55", "end_timestamp": "34:53", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "7d24c7ce-a5d6-4451-bcff-82086ecd13cd", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 16, "content": "Peter Williams (34:58): I mean, when I think about that, I go back to the kind of core values that got us off the ground and the reason I went over to Spencer's house that afternoon two summers ago and was talking about doing that, building ourselves a couple of these things, it's about getting outside and getting our kids outside and being able to live busy kind of urban lives without having a sacrifice of connection to the outdoors. And that sort of spontaneous, youthful spirit that is a little bit harder to hold onto as your life gets more complex and the responsibilities pack up. (35:35): So I think this is a fairly lofty response to that question, but I would super Pacific to become a company that is just making it easier for folks to get out and for kids to get out and keeping that sort of sparkle alive and in people's lives. But that's, as we grow the company and we start working out our accessory lines and product lines, I think we're going to be approaching each new endeavor from the perspective of how does this make it easier for folks to get out and have a good time and maintain that lifestyle throughout their lives.", "token_estimate": 287, "speakers": ["Peter Williams"], "start_timestamp": "34:58", "end_timestamp": "34:58", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "41d6a493-1737-4580-9b04-2b874414b066", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 17, "content": "Spencer Houser (36:16): And I think the other thing for us is that Peter and I are designers at heart, so we're always looking at things and always thinking, how could I improve on this? What would make this cooler? What would be cool if I had this thing or we added this accessory? And so in one sense, this company is just a means for Pete and Josh and I to just kind of realize some of those ideas that we're always having. I think the other thing too is that it's pretty exciting. So my family, I've got two daughters, a 13-year-old and 18-year-old daughter and my wife, and we've always camping and going outdoors has always been part of our thing. And we started it as tent camping, and then we got into travel trailers and we've had a number of travel trailers and really enjoyed that. But my kids are getting older, they're not so into trailers anymore. We wanted to try to, were always trying to take our trailers into places that you weren't supposed to bring trailers. And so we've kind of downsized and gotten into this, the truck camping a little bit more, but I've always kind of wanted, I've always thought RVs and trailers and the gear that we used, there was a lot of missed opportunity there. And so part of what we're doing, I think here too, is just making fulfilling the cool stuff that I've always had in the back of my mind. Right.\n\nCole Heilborn (38:09): Yeah. Sounds like it's just a tax write off for you guys to go camping.\n\nPeter Williams (38:13): Well, I mean,\n\nSpencer Houser (38:14): It's funny a certain extent,", "token_estimate": 386, "speakers": ["Spencer Houser", "Cole Heilborn", "Peter Williams"], "start_timestamp": "36:16", "end_timestamp": "38:14", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "7c74085b-9976-4cf2-9637-18bd2e4985e7", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 18, "content": "Peter Williams (38:17): Whenever I've gone, every time I go camping, I obsess on like, oh, I should pack this up this way. I should be sweet if I made a little box that everything fit like that. And it just popped in, popped out, and everything was super dialed. And I've always thought, man, it'd be a fun job. I've been in product design for a while now at different levels and different roles, but it's really fun to get to. I think right now we're building the engine, but what I want super specific to become, for me personally, is a way to get out in the woods and just have those ideas that I've always had and then figure out which ones to run down and turn that into the job that it is.\n\nCole Heilborn (38:59): I'm curious, because you guys just recently went through the transition of this being an idea to then being a lofty dream, to then being a part-time thing, to now being a full-time and more, what was the process like making the decision to quit the comfortable full-time job and jump into this? I think every founder or founders have to go through that process of leaving the safety net, whatever that is, and then deciding to jump into this thing that they're creating. What was that like for you guys?", "token_estimate": 306, "speakers": ["Peter Williams", "Cole Heilborn"], "start_timestamp": "38:17", "end_timestamp": "38:59", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "3cf4ed09-85d7-4159-b149-4ee14e70e104", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 19, "content": "Peter Williams (39:36): Well, Spencer's been full-time since the beginning because he came on full-time as soon as we basically started taking it seriously as a business opportunity. And then I was working on the side, so I had a full-time job. I was working in a part of Nike called The Space Kitchen, which is their most far from product innovation team. And it was a great job. I was super happy with it, and I was a carpenter for a long time, and when I decided I wanted to try to get into product design, it's a type of job I didn't know existed. (40:14): I couldn't have come up with, you'd shoot for that. I couldn't have come up with that job description when I was sitting in a pickup truck thinking, yeah, product design, that should be cool. But at any rate, so originally when we had that real slow growth model in mind, our intention was that we would grow Spencer's wage and he would run the business, and I would basically just do product design kind of on the side as a passion project sort of in my DNA. But as it unfolded, it became really obvious that this train was leaving the station. And if we were going to keep it on the rails, it was all hands on deck and it was really jarring. To be totally honest, I had to make a hard decision and we didn't have a lot of time to make it in, and it's been hard on myself and my wife and I went from working out of my garage during COVID and being home all the time to now the shop's super close to my house, but I'm here a lot. (41:21): I got to be in here. But that's been tough. Yeah, there's aspects of it that have definitely been tough, and we're in the sort of wild times right now where it's basically I stepped out of something that was very known and very predictable and comfortable into something that is very unknown and introduces some risk and some uncertainty into my home life and my reality. But when I have a minute to catch my breath and I can look up the light at the end of the tunnel is there, and I think that the end game is very exciting, but pushing through to it, it can be a lot right now. It's exhausting.", "token_estimate": 525, "speakers": ["Peter Williams"], "start_timestamp": "39:36", "end_timestamp": "39:36", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "c6198267-40a1-489c-b9ad-f0d23bf86d3d", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 20, "content": "Cole Heilborn (42:05): Yeah, no kidding. Well, I don't want to see how late you guys hang out in your shop every night. I feel like you guys are just always pushing midnight or beyond. At least that's what it seems like from the outside. So I hope you guys find some time to get some rest.\n\nSpencer Houser (42:24): Yeah, we sleep well sometimes.\n\nPeter Williams (42:28): Yeah, that has been true, Cole, and that's actually one of the things that has been really helpful for me getting through it is I've had our very first prototype on my truck for the summer and fall, and while there's an irony that the whole point of this business was to make it easier to get out with our families, we've been so consumed with the business that it's been pretty hard to get out with our families. But I have been able to do a lot of finish work on Friday, grab the team, grab a pizza, go up, sleep off a forest road, have a nice hike on Saturday and get back in. So it has, definitely having that thing on my truck has really facilitated my ability to get out with small pieces of time, which has been really, every time I do it, it's so refreshing and I'm like, okay, cool. This is cool. What we're doing is cool. I'm into it. So those little bits of recharge are super valuable, and like I said, it gets my focus back on that end game.\n\nCole Heilborn (43:32): Well said. So one of my last questions for you, we're running up on the end of our clock here. If you're thinking forward to year, five years from now, each of you, what's your individual's fear for the company as you guys look forwards? I guess I'm just curious, you guys are, I always, I'm curious to hear people's response to this question because if you could ask any of the founders of these giant brands that we are familiar with now, what their biggest fear was when they were first starting, I'd be really curious to know what those were. So if you could say something that you could look back on in 10 years when Super Pacific has a re on every pickup, what's your biggest fear at this point?", "token_estimate": 513, "speakers": ["Cole Heilborn", "Spencer Houser", "Peter Williams"], "start_timestamp": "42:05", "end_timestamp": "43:32", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "f8beb83e-50f1-4c33-a2b4-18e60657c768", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 21, "content": "Peter Williams (44:19): Well, I mean, you're going to have to answer because I'm going to have to think about this. Well, yeah, it's a sort of question you could dwell on for a while. I mean, fear of failure is, I feel like that's obvious, probably kind of a boring response.\n\nSpencer Houser (44:34): We're putting a lot on the line, both mentally, physically, financially, so that's always a big fear of the unknown kind of thing.\n\nPeter Williams (44:44): I think beyond that, I would say at this moment in the company, we've caught the ball and we're trying not to fumble. So I'm optimistic that we won't fail, but that's not really a driving fear. I think for me in this moment, just going through the transition that I have been going through, my biggest fear is that I will remain consumed with the business at such a level that I'll miss out on the whole reason that we did it and that it'll compromise my connections with my family and my chance to get out with my son while he is young and that stuff. I think if in 10 years I looked back and even if Super Pacific had manifested to my wildest dreams, if it had been at that cost, I think I would be fearful of that reality.\n\nSpencer Houser (45:33): Absolutely. Yep. Well, you got me thinking about a whole nother That's a great answer, Peter. I'm right there with you. How's\n\nPeter Williams (45:43): That? Thanks, bud.", "token_estimate": 345, "speakers": ["Peter Williams", "Spencer Houser"], "start_timestamp": "44:19", "end_timestamp": "45:43", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "1ba0147a-4bdd-4476-8639-800072fc9a4e", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 22, "content": "Spencer Houser (45:44): Yeah, I think, like Pete said, a fear of failure, maybe a fear of not being able to fulfill all the ideas that we have. I got a ton of ideas for just upgrades for just our current product line, and as the reality sets in of how long it actually takes to get things to happen, I think one of my biggest fears is that in five years, the things that I've thought of just now, if we haven't been able to fulfill those, I've only been able to fulfill half of those. That'll be disappointing because part of the fun of this company and the idea of starting this company is to, like I was saying before, is to be able use it as a means to just build cool stuff. But also, like Pete was saying, I think he and I can both really get obsessive and dive deep into things and turn you turn around, oh man, my kid's grown up, and what do we do here? And I guess the other fear is that if we're wildly successful and I can get all the dirt bikes, mountain bikes, scuba gear, fly fishing gear all and just continually do outdoor stuff, how am I going to hold up with all the outdoor stuff that we'll be doing?\n\nPeter Williams (47:25): Yeah, I'm pretty worried about sourcing duffel bags so I can the money in the backyard, right? That could be hard. In 10 years. I doubt there'll be enough duffel bags on the market.\n\nCole Heilborn (47:41): You should probably start talking up now just to prep yourself. Cool guys. Well, thanks for sharing. If folks want to follow along with either you personally or the company, where can folks go to connect?\n\nPeter Williams (47:56): Our website is a good spot. Super pacific usa.com and also Instagram, super Pacific USA underscore usa. Yep. And I think the Instagram is probably the key to the live updates, really.\n\nSpeaker 4 (48:11): Yeah.\n\nPeter Williams (48:12): Yeah. The website's a little dated actually at this point. We've put it up to get off the ground and haven't really looked at it since, so.\n\nCole Heilborn (48:20): Alright, well, sounds good. Are you guys going to be out adventuring in your rigs this weekend?", "token_estimate": 519, "speakers": ["Spencer Houser", "Peter Williams", "Cole Heilborn", "Speaker 4"], "start_timestamp": "45:44", "end_timestamp": "48:20", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "d4531a4d-0f33-4b94-b039-fb73f92ef5ca", "episode_id": "f13fc6c0-6d05-4a4c-8842-d431935ea94c", "cms_item_id": "68225dfc7bb476527f8c4857", "chunk_index": 23, "content": "Peter Williams (48:27): Yeah, we're going down to the coast. We're going to go do our first photography effort, so it'll be out live in the wild.\n\nSpencer Houser (48:36): It'll be a family effort, and so at least my kids are coming with me, so that's going to be fun.\n\nCole Heilborn (48:44): Well guys, keep up the good work. I'm excited to see where you go and to check in a year from now and see how much you guys have grown and see where you're at. Who knows, maybe there'll be a rig on every pickup by then. We hope so.\n\nPeter Williams (49:03): It's ambitious.\n\nSpencer Houser (49:03): Yeah, that's an ambitious call.\n\nCole Heilborn (49:07): Well, thanks again and have a good rest of your day.\n\nSpencer Houser (49:09): Hey, thanks very much, Cole. It's been a real pleasure to talk to you.\n\nPeter Williams (49:13): Yeah, good talking to you, Cole. Have a good day, man.\n\nSpencer Houser (49:15): See you.\n\nCole Heilborn (49:16): Alright. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 288, "speakers": ["Peter Williams", "Spencer Houser", "Cole Heilborn"], "start_timestamp": "48:27", "end_timestamp": "49:16", "podcast_index": 50, "episode_name": "Ep 50: Peter and Spencer | The Low Impact Camper | Super Pacific", "slug": "ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "web_url": "https://www.portsidepro.com/podcast-feed/ep-50-peter-and-spencer-the-low-impact-camper-super-pacific", "guest_name": "Peter Williams and Spencer Houser", "guest_title": "CoFounders, Super Pacific", "categories": [], "short_description": "Low Impact, Urban Lifestyle, and Truck Utility", "podcast_length": "44:72"}, {"id": "d23a1156-3775-459c-93ac-e2b6927829ec", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 0, "content": "Cory Van Auken (00:06): I think I just have so much to continue to learn, and I think there is, personally, my take on PR and marketing is, I'm not sure you can master it because it's changing so quickly. And so I think the pursuit of mastery is important, not the fact that you can become a master because I'm not sure you can or I certainly don't feel like I am. So for me personally, it's continuing that pursuit and not feeling comfortable in what I know and how we're doing it, but continue to push it further.\n\nCole Heilborn (00:42): Welcome to the Backcountry Marketing podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole, he born. Today I'm sitting down with Corey von Akin, the Digital relations Director at Darby Communications. Corey, how are you doing?\n\nCory Van Auken (01:24): Hey, Cole. I'm doing great. Thanks for having me. I appreciate it. How's everything going in the Pacific Northwest?\n\nCole Heilborn (01:31): Its good. It's wet and cloudy. So not much of a surprise there, but where are you joining us from today?\n\nCory Van Auken (01:40): I'm in Asheville and North Carolina, so I'm pretty lucky. It's a little chilly out here right now, but it's beautiful and sunny, so things are good.\n\nCole Heilborn (01:49): I'm assuming you guys don't get a whole lot of white Christmases down there.", "token_estimate": 462, "speakers": ["Cory Van Auken", "Cole Heilborn"], "start_timestamp": "00:06", "end_timestamp": "01:49", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "5e45751b-7f25-45c7-a7b9-3b5f3d43017d", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 1, "content": "Cory Van Auken (01:52): Not a ton. We'll get a little bit and anytime we get a little bit, everyone gets excited. So we had a little bit of the snow last week and we may get something, but it's typically maybe two to three times a year we get a dusting or two. Occasionally. Occasionally we'll get a storm and one of the first times I had seen snow here, we had a 12 that came through, which was a lot of fun. So occasionally, what about you? Are you going to get?\n\nCole Heilborn (02:24): We don't get much of anything. We maybe once every five years get a little bit of snow on Christmas day for all the folks who live in the north, like the Midwest who are listening to this right now. They're probably making fun of us because we're getting excited if we get half an inch of snow on Christmas, meanwhile they're buried feet under,\n\nCory Van Auken (02:44): Hey, we deserve that. I'm from Massachusetts, and so my dad will think what I said is cringey. So totally\n\nCole Heilborn (02:51): Get it. Well, I'm super excited to have you on the show today. Maybe before we jump in, do you want to give us a bit of a background on Darby, who you guys are, what you guys do?\n\nCory Van Auken (03:01): Sure. Darby Communications is a PR and digital marketing agency. We're based here in Asheville, North Carolina. We've been around for over a decade and servicing international, national, regional and local clients in the outdoor hunt fish over overlanding fitness and wellness industries to name a few.\n\nCole Heilborn (03:21): Okay, right on. And do you guys do some work, I'm trying to remember some of your main clients, Sierra Designs, old Town Canoe and Kayak. Are there any others that I'm missing?\n\nCory Van Auken (03:31): Yeah, we've a bunch Sierra Designs Old Town, like you said, ocean Kayak Industrial Revolution, which based up near you, which is Yuko Gear, Moura, KVE, lifesaver, astral, obras Highlands. We have a bunch more. But yeah, those are a few. So fun clients to work with, man, enjoy getting outside with the products. So", "token_estimate": 509, "speakers": ["Cory Van Auken", "Cole Heilborn"], "start_timestamp": "01:52", "end_timestamp": "03:31", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "6ca966a3-57d4-4811-91b1-32ee448ed06d", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 2, "content": "Cole Heilborn (03:52): Yeah, it's funny you mentioned the guys over at Obras. By this time this episode has come out, the Obras episode will already be out, and those guys, Jensen and Nikolai are two pretty rad dudes who are actually here in the Seattle area. And I highly encourage folks who are listening to go listen to that episode if they want to learn more about how you can make a pair of sunglasses without any arms, and if you just want to hear their crazy startup story and where their company's going, it's pretty cool.\n\nCory Van Auken (04:21): Oh, those guys are great. Yeah, I work with those guys a lot and they are hilarious, but really savvy and what they're doing up there and you're a little pocket is pretty cool. And talk about guys that are totally dialed in on their marketing and really speaking to their audience. So yeah, because I haven't listened to that yet. It hasn't come out. I will have listened to it when this comes out and I'm sure it's going to be entertaining.\n\nCole Heilborn (04:50): Yeah, they were a lot of fun. It was fun chatting with them. I think. I wish I could remember specifically, but Nikolai was somewhere in Mexico or on the Baja Peninsula while we were doing his interview. One of the guys was, I don't remember, but I think it\n\nCory Van Auken (05:04): Was Jensen, he went to, maybe it was\n\nCole Heilborn (05:06): Jensen,\n\nCory Van Auken (05:06): But he also has, I was on a call with him, I was like, Hey, you're breaking up a little bit, where are you? And he is like, I'm actually in Mexico right now, but he was also doing some shoots, I think for some of their marketing too. So yeah, you never know what they're going to be up to. They're a lot of fun.\n\nCole Heilborn (05:23): Yeah. Well, we're recording this right now a couple of weeks before Christmas at the end of the year, and I feel like in the PR world, you guys have got to be pretty busy right now. I see so many of those holiday gift gear trend things popping up everywhere, and I think I've seen you guys putting stuff out on behalf of your clients or managing that stuff. So how's the end of the year treating you guys and are you guys staying busy?", "token_estimate": 543, "speakers": ["Cole Heilborn", "Cory Van Auken"], "start_timestamp": "03:52", "end_timestamp": "05:23", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "93709d08-7541-4cd2-aeba-20305fb6df06", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 3, "content": "Cory Van Auken (05:50): Yeah, that's a great question. So holiday gift guide season starts for us oftentimes in July, late July. Does it? Yeah. So if you can imagine having to get, you're in the middle of summer and you're having to turn your mindset a bit into holiday gift guides easy now, that's for long lead publications. So publications that take a while and for example, outside magazine typically test their stuff for a really long time, upwards of sometimes eight months. So we'll start thinking about holiday gift guide season starting in July and into August, and then we really get into the meat of it with shorter lead digital pieces coming in September, October and November. We're kind of towards more of the tail end, if you can believe it right now, even though it is holiday gift guide season right now, most of the time we're in the tail end unless it's super short lead where we're trying to get coverage immediately. (06:45): But yeah, so we've been super busy, typically on the PR side of things. It starts to quiet down starting next week, and as we get into the holiday season, nobody likes a bunch of calls and emails when they're trying to prepare to rest and relax. So oftentimes we do the same thing and then get ready to plan for the next year or so. As we're recording this, we're starting to plan for our clients for 2021, so we're trying to get to the tail end of it. Quick question for you. I know you're somebody who gets at it, gets out and about. Do you do any of your shopping using holiday gift guides at all? Do you ever find any interesting products? And\n\nCole Heilborn (07:31): I got to think about this. You're asking a multilayered question because you're also asking, how much do I participate in buying gifts at the end of the year?\n\nCory Van Auken (07:40): Oh, do you plan ahead? Because even better.", "token_estimate": 462, "speakers": ["Cory Van Auken", "Cole Heilborn"], "start_timestamp": "05:50", "end_timestamp": "07:40", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "0b8d8871-2a5a-45ff-bb24-7fbf3cab9ae5", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 4, "content": "Cole Heilborn (07:48): So my family and my wife, we don't buy a ton of gifts. (07:53): We'll usually buy, I've bought my wife a couple things. I bought my immediate family a few things, but we don't do a whole lot of it. So I feel like I'm not the best person to ask that. And usually the things that we do end up buying then are pretty particular things that someone has made a comment about what they want or something that they would like throughout the year, and we just try to keep tabs on that and then remember that. So my wife makes comments throughout the year and I try to put those in a mental box and then remember those for Christmas time.\n\nCory Van Auken (08:28): You're very smart.\n\nCole Heilborn (08:29): Well, she has to remind me frequently, but I don't know that I use a ton of those gift guides to purchase in the holiday season. I think what I'd like is seeing them and it kind of exposes me to just new products that are out there and maybe that influences me for next year. I don't know.\n\nCory Van Auken (08:48): Yeah, totally. I found myself, because I'm involved with it for a good portion of the year, I now use more holiday gift guides than I have in previous years because I'm involved with it. So it gives me some good ideas and a good approach to figuring out things if I haven't planned as far ahead where it sounds like you're planning ahead, which is kind of nice. So I might need to take some tips.\n\nCole Heilborn (09:13): Well, I don't know about that. I mean, we're two or three weeks away from Christmas and I just kind of started getting my wheels turning about what I should go by. Anyways, I'm excited to learn a little bit more about your role as a digital relations director. Can you fill us in as to what that means?", "token_estimate": 440, "speakers": ["Cole Heilborn", "Cory Van Auken"], "start_timestamp": "07:48", "end_timestamp": "09:13", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "a9785230-8a24-45d7-b51c-c26af3e91ad6", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 5, "content": "Cory Van Auken (09:30): Yeah, so my job as digital relations director at darby com is really to determine and ultimately help facilitate the best practices on how we as an agency can break down. We try really hard to break down the silos between our communications team and the marketing teams for the brands that we work with, and then how we can best practices for measuring the impact of the work we do and directly correlating that. I'm sure we'll get into that a little bit today. Then I specifically work hard at analyzing that impact and trying to take things away from that in our analysis and then report on it and continue to use this information to make more increasingly informed decisions which comes. There's a whole host of stuff associated with that. So oftentimes I'm in the weeds with analytics and with data and it's a lot of fun and involves a lot of strategy, so I enjoy it.\n\nCole Heilborn (10:34): Yeah. So are you kind of the liaison between the client and Darby comm or is there more of a collaborative approach between Darby comm and your clients, or how is that structured?", "token_estimate": 275, "speakers": ["Cory Van Auken", "Cole Heilborn"], "start_timestamp": "09:30", "end_timestamp": "10:34", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "d0aab447-635a-4a45-ae00-15e6fb38f04c", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 6, "content": "Cory Van Auken (10:45): Yeah, it's a great question. So I think something that's pretty unique about darby com is we take a team approach with each client that we have. So every client gets a Darby account lead and team member, and then depending on the services that they need will have a few other teammates involved. So I'm typically, I work with a host of clients as well, so I have a team of clients as well, but I typically set best practices across our agency how we all will be pulling reports and each account lead pulls their own report, analyzes it, but I do the facilitation of that and then can step in on certain levels of things there too. So we're lucky that we get to work with a number of different clients, but I think what is really unique and special about some of the relationships we have with clients, we're working with some clients that we've worked with for over 10 years, and they don't just have one person that represents Starcom. They have two, sometimes three people as their own communications team, and we try to integrate that directly with their marketing team so we work hand in hand. Does that make sense?\n\nCole Heilborn (11:59): Yeah, no, so you guys are just kind of an extension of the internal team or whatever the internal team looks like. Sometimes it's just the founder, sometimes it's a couple of people on the inside, is that right?\n\nCory Van Auken (12:09): Exactly, yeah. And we try to be, and it takes different forms depending on how large the company is. So you've nailed it. Yep.", "token_estimate": 383, "speakers": ["Cory Van Auken", "Cole Heilborn"], "start_timestamp": "10:45", "end_timestamp": "12:09", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "496a0c20-3860-4a49-91c9-5532d7b164e9", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 7, "content": "Cole Heilborn (12:17): Okay. So I'm curious to learn a little bit more about the world of pr and we've had some experts on the show who have talked about just the world of pr. Chris Dickey was one of 'em, he's a previous episode. He runs the agency purple and orange, and they do some really awesome work. They're pretty known in the industry, and we talked a lot about SEO and actually a new side project that he's been developing called Visibly, but we didn't talk a whole lot about PR and kind of the digital marketing side. And I'm curious to learn a little bit more about your guys' perspective on those two. Do they overlap? Do they work well together? Do they not work well together? And especially now when I feel like everything is digital, is there really just organic true PR as it used to be?", "token_estimate": 201, "speakers": ["Cole Heilborn"], "start_timestamp": "12:17", "end_timestamp": "12:17", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "6f959a51-28e8-4f05-a1ba-b67d76856dad", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 8, "content": "Cory Van Auken (13:05): Yeah, those are great questions. So we'll see if I can unpack a little bit and maybe provide my opinion. But first I wanted to say that episode that you had with Chris, he does some really amazing work on the digital SEO side and where PR can fit in with SEO and he's doing some cool stuff. We're in this same industry and yeah, he's cool guys. So that was a great episode and it was definitely helpful to learn too. So always love to learn in any case. So I would say to start answering that question and break it down a bit, historically, PR and communications and marketing have been siloed and we had just talked about how we now, most cases the silos are kind of broken and working together, but historically they've been siloed and PR was used to gain awareness for products, services, or personalities of a company via trusted third party validation and gain that third party validation. (14:01): On the other side, marketing and digital marketing were used to connect clients' products to customers and then kind of usher them down through their customer journey and into sales. And what I think marketers and specifically digital marketers have been really good at, they've been much quicker to adapt to the changing technology landscape that we find ourselves in and to measure true impact of their work and what the ROI is of their efforts. They're always on the cutting edge of that. And I think historically, and I could say this as a PR practitioner, I think we've not done a good job historically as as an umbrella in measuring the impact of the work that we do. And the measurement has typically been, and still in some cases for some PR practitioners, it's a bit antiquated. It's a bit arm wavy in some cases, and I think we can do better. (15:01): And so it often has borrowed measurement techniques from paid media sources like at equivalency value or readership or impression numbers. And that's okay, but it doesn't give you really a full picture of the impact. And this has slowly started to evolve into reach for unique visitors per month on the digital side, but there's so much more that we do. And so I think now is a really exciting time in the earned media and the PR world because there's less barriers to connect earned media with the impact that it's producing for brands, whether it be a brand awareness impact or a digital impact or a bottom line pact.", "token_estimate": 603, "speakers": ["Cory Van Auken"], "start_timestamp": "13:05", "end_timestamp": "13:05", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "e1ffaea7-dad1-4564-8599-47d9e1dbc235", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 9, "content": "Cole Heilborn (15:44): Gotcha. So a couple of questions out of that one. Why have those typically been siloed in the past and what has motivated the breaking down of the silos, as you say?\n\nCory Van Auken (15:58): Yeah, that's a great question. I don't know if I can answer that specifically to try my best there. I think they've been siloed in the past because they've been viewed as two different entities that are necessary but don't have a lot of overlap. And I think what's starting to see is that actually they have a ton of overlap, and then when they're paired together, they amplify what each other are doing, if that makes sense. And so I think we'll get into this at some point too, but one of what we really try to do at darby com and other PR agencies do this as well, and this is how you're working with an agency that's really working alongside a marketing department, is figuring out ways to amplify the earned media once you've captured it. So in a lot of ways, you can get this really great piece of coverage and sometimes it's great to pat ourselves on the back and say, that was awesome, but that's only really 50% of the impact. (16:58): If you leave it there, you're leaving 50% of the impact on the table. And so if you can work with the marketing team to figure out how to use that third party validation that you just got from a really respected source and use it across, let's say their owned channels, and can we figure out how to create content using this and showcase it? Can we use it in our email marketing campaigns to provide that validation? Can we use it for our own social media content or social media ads? And that way you can provide even more impact with a single piece of coverage.\n\nCole Heilborn (17:35): Gotcha.\n\nCory Van Auken (17:36): Does that make sense?", "token_estimate": 451, "speakers": ["Cole Heilborn", "Cory Van Auken"], "start_timestamp": "15:44", "end_timestamp": "17:36", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "8784bca0-a246-437e-8bee-f7777391bb13", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 10, "content": "Cole Heilborn (17:37): No, that makes sense. And I feel like, I mean, that way of thinking sounds really obvious. Like, oh, we just got a review in some Gear magazine, why wouldn't we turn that into a whole bunch of other content and get it out there and get the word out there? But that hasn't always been the case. I guess that's what I find interesting is why wouldn't people be doing that? Why is it taking so long? Or maybe,\n\nCory Van Auken (17:59): Yeah, and I think it's obvious now, and it might not have been obvious before because now we have the tools to be able to measure the impact of it. And in a lot of ways these tools, and by tools we mean Google Analytics is a great example of how we use Google Analytics all the time as PR practitioners to see what our impact has been in a lot of ways. And we share that. And what it's done is created way more transparency in the work that we do. And I think transparency is key because before, if there wasn't a whole lot of transparency and if there is no transparency in the work that you're doing, I think that leads to misunderstanding in both camps. And from there, like you said, it would seem obvious, but you don't have all the information. So now we have the tools to be able to measure it. And so yeah, I think it seems obvious now because it's working.\n\nCole Heilborn (19:05): Sure. So when you talk about measuring the impact of a PR, or let's just keep using this example of a holiday gift guide, how do you guys start to quantify impact? What ways do you measure that? What are ways that you can, what are tools that you can trust? What are some that you maybe look at but don't take them at face value? Because a bunch of tools out there in the digital marketing world, some of which you've mentioned, reach, impression distribution for the article or the organization that's doing the review. How do you manage all that?", "token_estimate": 474, "speakers": ["Cole Heilborn", "Cory Van Auken"], "start_timestamp": "17:37", "end_timestamp": "19:05", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "83b2a299-c9fd-4c31-822a-08d000b1f22e", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 11, "content": "Cory Van Auken (19:43): Yeah, that's a great question. And I think it depends on the type of coverage that you get. So let's go with the holiday gift guide example, and we'll go with the holiday gift guide example where you have a specific product from a brand that we're working with and the piece of coverage links directly to their website. So we're able to link that piece of PR to behavior. And what I mean by that is we can connect earned media consumption to web traffic and then track those people's journeys. So someone, let's say I read that holiday gift guide. I see this product that I'm really interested in, I click from, let's say it was on Gear Junkie for example. They do a great job with their holiday gift guides and they have some awesome gear. So I click from Gear Junkie onto the brand's website. As a PR practitioner, I can measure the journey of that person. (20:38): And so we gather acquisition metrics, so user sessions, those kinds of things. We gather behavior metrics, what are they doing once they get to the site? Are they bouncing immediately? How many pages are they viewing per session? What's the session duration? Things like that. And then we can also measure conversion metrics depending on how people have their Google Analytics set up. But is this leading to e-commerce and last click conversions that's really easy to show ROI there, or is this leading to some goal completion? So if it's a larger product, let's say like a kayak and some kayaks can be a pretty hefty investment, sometimes it takes a lot of touch points and maybe I'm not ready to purchase just from reading that holiday gift guide, but I did go to a product view page and I scrolled down and watched the video and maybe I achieved a few goals. (21:34): There's certain value in that as well. So that's what we start to measure now. Totally. That's one example of a digital piece of coverage that directly links. And I think your question, and where PR continues to figure this out is in pieces of coverage that you can't automatically measure the direct impact. What do you use to get a good idea? And I think that's a question that PR as a whole in communications is continuing to grapple with. So a piece of print coverage, there's tons of value in that, but how do you express that value truthfully, and how do you express it without over-inflating its value or underinflating it? And so something that we look at is if we were just looking at what we can measure directly, brands would, you would think naturally it would eventually lead to brands just wanting digital pieces of coverage that link directly. But we can cover everything. But there is a lot of value in appearing on a podcast. There's a lot of value on a great piece of print coverage. And so what we've worked really hard at is trying to disseminate that value and analyze it and then present it in a way that's truthful. And so we've done a bunch of work on that in the last three or four years do that. And so our reporting system's pretty robust. And yeah, we're pretty proud of it. We work pretty hard on it.", "token_estimate": 773, "speakers": ["Cory Van Auken"], "start_timestamp": "19:43", "end_timestamp": "19:43", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "cdd43c62-f186-406a-8590-6cfd2b85b842", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 12, "content": "Cole Heilborn (23:09): Yeah, I think it's cool. I hope this is the case, but I think we're starting to see some of those endemic print coffee table magazines starting to make a comeback or they're starting to become more popular these days. There's a couple that I really enjoy. One of 'em is that my buddy's over at the Free Hub magazine, they're a bike endemic magazine and they do beautiful work. It's a quarterly magazine. All the stories and the photos are rich and stunning, and all the ads in them too are just, you want to look at it, you're like, oh, this is cool. Other than the visual beauty that I really appreciate. How do you begin to quantify the value of an ad like that in an endemic magazine or any magazine when you don't have all those digital tools? All you maybe have is the print magazine circulation size?\n\nCory Van Auken (24:02): Yeah, that's a great question and I can't speak to the ad side of things. I don't do much on the ad work, but let's say the same example, but on the earn side, and let's say we get a really good brand piece in a piece of coverage, I think there's something to be said for the fact that it's coming back and everyone predicted that it would, but it is, and we believe the reason for that is, and you tell me what you think because you love reading. Did you say it was Free Hub?\n\nSpeaker 3 (24:29): Yeah,", "token_estimate": 340, "speakers": ["Cole Heilborn", "Cory Van Auken", "Speaker 3"], "start_timestamp": "23:09", "end_timestamp": "24:29", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}, {"id": "5e66d4a9-ee66-408b-87c2-c81b24a89964", "episode_id": "58fd0630-891d-4c4d-a89d-96aad5a6ae04", "cms_item_id": "68225dfc7bb476527f8c4856", "chunk_index": 13, "content": "Cory Van Auken (24:30): Yeah. And there's a number of different publications where you just really are looking forward to receiving that because you're paying for that subscription, you're inviting it into your home. I think a lot of marketing these days, you're getting bombarded with things that you're not necessarily asking to be bombarded with. If you go on Facebook, you can't scroll down your feed more than a few little scrolls before just getting bombarded with all sorts of product. And maybe you haven't asked for that. So I think what's really special about print is that they spent a lot of time curating it and it's invited into your home and it's tactile and it really is artwork in some ways, and it is truly beautiful. And when you think about what you do when you open a magazine and read it, you're spending let's say an hour of uninterrupted time consuming that because you want to and you trust them. (25:28): And so that trust is hard to quantify, and I don't know if you could truly quantify it in the same way that you would quantify it with digital marketing practices. And so what we've tried to do is we've designed a proprietary algorithm that gathers tens of data points and various metrics on each piece of coverage no matter what the coverage medium is. So whether it's print, digital, social podcast, and that algorithm is designed and it takes all of these pieces of data and metrics into account to try to visually represent the value of each piece of coverage. And so that's how we're trying to do it right now. It's been wonderful to a really engaging project, but it's not without its challenges, especially to try to ensure that when building this algorithm that we don't put our personal biases into it, which there's obviously going to be some, but if you're building the algorithm and you really love free hub, you want to make sure that you're not overweighting things and we need to use it across all of our clients, all of our clients are different. So figuring out how to do that and it working for all of our clients was another challenge.", "token_estimate": 522, "speakers": ["Cory Van Auken"], "start_timestamp": "24:30", "end_timestamp": "24:30", "podcast_index": 51, "episode_name": "Ep 51: Cory Van Auken | Digital Marketing and PR | Darby Communications", "slug": "ep-51", "web_url": "https://www.portsidepro.com/podcast-feed/ep-51", "guest_name": "Cory Van Auken", "guest_title": "Darby Communications", "categories": [], "short_description": "We go deep inside Darby's approach to analyze how they integrate digital and PR", "podcast_length": "44:73"}]
